                                                        <FocusAwareSidebar>
                                                            <AppSidebar />
                                                        </FocusAwareSidebar>
                                                        <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                                                            <FocusAwareMobileHeader>
