"use client";

import { useState, useRef, useCallback, useEffect } from "react";
import { cn, formatNumber } from "@/lib/utils";
import {
    Sparkles,
    Pause,
    Play,
    Loader2,
    CheckCircle2,
    StopCircle,
    GripHorizontal,
    Minimize2,
    Maximize2,
} from "lucide-react";
import type { JobStatus } from "@/hooks/use-analysis";

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface FloatingStatusProps {
    status: JobStatus;
    progress: number;
    total: number;
    changesCount: number;
    currentTrack: string;
    onOpen: () => void;
    onPause: () => Promise<void>;
    onResume: () => Promise<void>;
}

// ΓöÇΓöÇΓöÇ Position Persistence ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const WIDGET_POS_KEY = "analysis-widget-position";

function loadWidgetPosition(): { x: number; y: number } | null {
    try {
        const raw = localStorage.getItem(WIDGET_POS_KEY);
        if (!raw) return null;
        const pos = JSON.parse(raw);
        if (typeof pos.x === "number" && typeof pos.y === "number") return pos;
    } catch { }
    return null;
}

function saveWidgetPosition(pos: { x: number; y: number }) {
    try {
        localStorage.setItem(WIDGET_POS_KEY, JSON.stringify(pos));
    } catch { }
}

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export function AnalysisFloatingStatus({
    status,
    progress,
    total,
    changesCount,
    currentTrack,
    onOpen,
    onPause,
    onResume,
}: FloatingStatusProps) {
    // ΓöÇΓöÇΓöÇ Drag State ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [position, setPosition] = useState(() => {
        return loadWidgetPosition() ?? { x: 20, y: 20 };
    });
    const [isDragging, setIsDragging] = useState(false);
    const didDragRef = useRef(false);
    const dragStart = useRef({ x: 0, y: 0, posX: 0, posY: 0 });
    const containerRef = useRef<HTMLDivElement>(null);

    const onPointerDown = useCallback(
        (e: React.PointerEvent) => {
            e.preventDefault();
            setIsDragging(true);
            didDragRef.current = false;
            dragStart.current = {
                x: e.clientX,
                y: e.clientY,
                posX: position.x,
                posY: position.y,
            };
            (e.target as HTMLElement).setPointerCapture(e.pointerId);
        },
        [position]
    );

    const onPointerMove = useCallback(
        (e: React.PointerEvent) => {
            if (!isDragging) return;
            didDragRef.current = true;
            const dx = e.clientX - dragStart.current.x;
            const dy = e.clientY - dragStart.current.y;
            const newX = dragStart.current.posX + dx;
            const newY = dragStart.current.posY + dy;

            // Clamp to viewport
            const maxX = window.innerWidth - 60;
            const maxY = window.innerHeight - 40;
            setPosition({
                x: Math.max(0, Math.min(newX, maxX)),
                y: Math.max(0, Math.min(newY, maxY)),
            });
        },
        [isDragging]
    );

    const onPointerUp = useCallback(() => {
        setIsDragging(false);
        if (didDragRef.current) {
            // Save final position after drag
            setPosition(pos => {
                saveWidgetPosition(pos);
                return pos;
            });
        }
    }, []);

    // ΓöÇΓöÇΓöÇ Position initialization (bottom-right, only if no saved position) ΓöÇ
    useEffect(() => {
        const saved = loadWidgetPosition();
        if (!saved) {
            setPosition({
                x: window.innerWidth - 340,
                y: window.innerHeight - 140,
            });
        }
    }, []);

    // ΓöÇΓöÇΓöÇ Derived ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const pct = total > 0 ? Math.round((progress / total) * 100) : 0;
    const isRunning = status === "running";
    const isPaused = status === "paused";
    const isDone = status === "completed" || status === "stopped";

    // ΓöÇΓöÇΓöÇ Minimize ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [minimized, setMinimized] = useState(false);

    // Minimized pill
    if (minimized) {
        return (
            <div
                ref={containerRef}
                className="fixed z-50 select-none animate-in fade-in slide-in-from-bottom-2 duration-200"
                style={{ left: position.x, top: position.y }}
            >
                <div
                    className={cn(
                        "flex items-center gap-2 rounded-full border px-3 py-1.5 shadow-lg backdrop-blur-xl cursor-pointer",
                        isDone ? "border-green-500/30 bg-[var(--card)]/95" :
                            isPaused ? "border-amber-500/30 bg-[var(--card)]/95" :
                                "border-purple-500/30 bg-[var(--card)]/95"
                    )}
                    onClick={() => setMinimized(false)}
                >
                    <div
                        className={cn(isDragging ? "cursor-grabbing" : "cursor-grab")}
                        onPointerDown={onPointerDown}
                        onPointerMove={onPointerMove}
                        onPointerUp={onPointerUp}
                    >
                        <GripHorizontal className="h-3 w-3 text-[var(--muted-foreground)]" />
                    </div>
                    {isRunning && <Loader2 className="h-3 w-3 text-purple-400 animate-spin" />}
                    {isPaused && <Pause className="h-3 w-3 text-amber-400" />}
                    {isDone && <CheckCircle2 className="h-3 w-3 text-green-400" />}
                    <span className="text-[10px] font-bold tabular-nums">
                        {isDone ? "Done" : `${pct}%`}
                    </span>
                    <span className="text-[9px] text-[var(--muted-foreground)] tabular-nums">
                        {progress}/{total}
                    </span>
                </div>
            </div>
        );
    }

    return (
        <div
            ref={containerRef}
            className={cn(
                "fixed z-50 select-none",
                "animate-in fade-in slide-in-from-bottom-4 duration-300"
            )}
            style={{
                left: position.x,
                top: position.y,
                transition: isDragging ? "none" : "box-shadow 0.2s",
            }}
        >
            <div
                className={cn(
                    "flex flex-col rounded-2xl border shadow-2xl backdrop-blur-xl",
                    "w-[300px] overflow-hidden",
                    isDone
                        ? "border-green-500/30 bg-[var(--card)]/95"
                        : isPaused
                            ? "border-amber-500/30 bg-[var(--card)]/95"
                            : "border-purple-500/30 bg-[var(--card)]/95"
                )}
            >
                {/* Progress bar (thin top bar) */}
                {!isDone && (
                    <div className="h-1 w-full bg-[var(--secondary)]">
                        <div
                            className={cn(
                                "h-full transition-[width] duration-700 ease-out",
                                isPaused
                                    ? "bg-gradient-to-r from-amber-500 to-orange-500"
                                    : "bg-gradient-to-r from-purple-500 to-pink-500"
                            )}
                            style={{ width: `${pct}%` }}
                        />
                    </div>
                )}

                {/* Header row ΓÇö drag handle + title */}
                <div className="flex items-center gap-2 px-3 pt-2.5 pb-1">
                    {/* Drag handle */}
                    <div
                        className={cn(
                            "flex items-center justify-center rounded p-0.5 text-[var(--muted-foreground)] hover:text-[var(--foreground)] hover:bg-[var(--accent)]",
                            isDragging ? "cursor-grabbing" : "cursor-grab"
                        )}
                        onPointerDown={onPointerDown}
                        onPointerMove={onPointerMove}
                        onPointerUp={onPointerUp}
                    >
                        <GripHorizontal className="h-3.5 w-3.5" />
                    </div>

                    {/* Status icon + label */}
                    <div className="flex items-center gap-1.5 flex-1 min-w-0">
                        {isRunning && (
                            <Loader2 className="h-3.5 w-3.5 text-purple-400 animate-spin shrink-0" />
                        )}
                        {isPaused && (
                            <Pause className="h-3.5 w-3.5 text-amber-400 shrink-0" />
                        )}
                        {isDone && (
                            <CheckCircle2 className="h-3.5 w-3.5 text-green-400 shrink-0" />
                        )}
                        <span className="text-xs font-medium truncate">
                            {isRunning && "Analyzing Library"}
                            {isPaused && "Analysis Paused"}
                            {isDone &&
                                `Analysis Done ΓÇö ${changesCount} updates`}
                        </span>
                    </div>

                    {/* Percentage */}
                    {!isDone && (
                        <span className="text-xs font-mono font-bold text-purple-400 tabular-nums shrink-0">
                            {pct}%
                        </span>
                    )}

                    {/* Minimize */}
                    <button
                        onClick={(e) => { e.stopPropagation(); setMinimized(true); }}
                        className="p-0.5 rounded text-[var(--muted-foreground)] hover:text-[var(--foreground)] hover:bg-[var(--accent)] transition-colors cursor-pointer shrink-0"
                    >
                        <Minimize2 className="h-3 w-3" />
                    </button>
                </div>

                {/* Track info */}
                {!isDone && currentTrack && (
                    <div className="px-3 pb-1">
                        <p className="text-[10px] text-[var(--muted-foreground)] truncate">
                            {currentTrack}
                        </p>
                    </div>
                )}

                {/* Stats row */}
                <div className="flex items-center gap-3 px-3 pb-2 text-[10px] text-[var(--muted-foreground)]">
                    <span className="tabular-nums">
                        <span className="text-[var(--foreground)] font-medium">
                            {formatNumber(progress)}
                        </span>
                        /{formatNumber(total)} tracks
                    </span>
                    <span className="tabular-nums">
                        <span className="text-green-400 font-medium">
                            {changesCount}
                        </span>{" "}
                        updates
                    </span>
                </div>

                {/* Action row */}
                <div className="flex items-center border-t border-[var(--border)] divide-x divide-[var(--border)]">
                    {/* Pause/Resume toggle */}
                    {!isDone && (
                        <button
                            onClick={(e) => {
                                e.stopPropagation();
                                isRunning ? onPause() : onResume();
                            }}
                            className={cn(
                                "flex items-center justify-center gap-1.5 flex-1 py-2 text-xs transition-colors cursor-pointer",
                                "hover:bg-[var(--accent)]",
                                isPaused
                                    ? "text-green-400 hover:text-green-300"
                                    : "text-amber-400 hover:text-amber-300"
                            )}
                        >
                            {isRunning ? (
                                <>
                                    <Pause className="h-3 w-3" />
                                    Pause
                                </>
                            ) : (
                                <>
                                    <Play className="h-3 w-3" />
                                    Resume
                                </>
                            )}
                        </button>
                    )}

                    {/* Open modal */}
                    <button
                        onClick={onOpen}
                        className={cn(
                            "flex items-center justify-center gap-1.5 flex-1 py-2 text-xs transition-colors cursor-pointer",
                            "text-purple-400 hover:text-purple-300 hover:bg-[var(--accent)]"
                        )}
                    >
                        <Sparkles className="h-3 w-3" />
                        {isDone ? "Review Changes" : "Open"}
                    </button>
                </div>
            </div>
        </div>
    );
}

"use client";

import {
    useState,
    useEffect,
    useCallback,
    type ReactNode,
} from "react";
import {
    useAnalysis,
    checkAnalysisStatus,
} from "@/hooks/use-analysis";
import {
    AnalysisContext,
    type AnalysisContextValue,
} from "@/hooks/analysis-context";
import { AnalyzeModal } from "@/components/analyze-modal-v2";
import { AnalysisFloatingStatus } from "@/components/analysis-floating-status";
import { useRenderCount } from "@/lib/dev-debugger";

export { useAnalysisContext } from "@/hooks/analysis-context";

// ΓöÇΓöÇΓöÇ Provider ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const ANALYSIS_MODAL_KEY = "analysis-modal-open";

function loadModalOpen(): boolean {
    if (typeof window === "undefined") return false;
    try {
        return localStorage.getItem(ANALYSIS_MODAL_KEY) === "true";
    } catch {
        return false;
    }
}

function saveModalOpen(open: boolean) {
    try {
        if (open) {
            localStorage.setItem(ANALYSIS_MODAL_KEY, "true");
        } else {
            localStorage.removeItem(ANALYSIS_MODAL_KEY);
        }
    } catch { }
}

export function AnalysisProvider({ children }: { children: ReactNode }) {
    useRenderCount("AnalysisProvider");
    const [modalOpen, setModalOpen] = useState(false);

    // SSE should be connected when analysis is active OR modal is open
    const [sseEnabled, setSseEnabled] = useState(false);
    const analysis = useAnalysis(sseEnabled);

    // Determine if SSE should be on
    const isActive =
        analysis.status === "running" || analysis.status === "paused";
    const needsReview =
        analysis.status === "completed" || analysis.status === "stopped";

    useEffect(() => {
        setSseEnabled(modalOpen || isActive);
    }, [modalOpen, isActive]);

    // Persist modal open state
    const handleModalChange = useCallback((open: boolean) => {
        setModalOpen(open);
        saveModalOpen(open);
    }, []);

    // On mount: only re-open modal if it was open before AND analysis is active
    useEffect(() => {
        const wasOpen = loadModalOpen();
        checkAnalysisStatus().then((status) => {
            const active = status.status === "running" || status.status === "paused";
            const hasResults = status.status === "completed" || status.status === "stopped";
            if (wasOpen && (active || hasResults)) {
                setModalOpen(true);
                setSseEnabled(true);
            } else if (!active && !hasResults) {
                // Analysis is idle ΓÇö clear the persisted flag
                saveModalOpen(false);
            }
            // If analysis is active but modal wasn't open, just enable SSE for floating widget
            if (!wasOpen && (active || hasResults)) {
                setSseEnabled(true);
            }
        });
    }, []);

    const openModal = useCallback(() => handleModalChange(true), [handleModalChange]);
    const closeModal = useCallback(() => handleModalChange(false), [handleModalChange]);

    const value: AnalysisContextValue = {
        ...analysis,
        modalOpen,
        openModal,
        closeModal,
        start: analysis.start,
        pause: analysis.pause,
        resume: analysis.resume,
        stop: analysis.stop,
        reset: analysis.reset,
        fetchChanges: analysis.fetchChanges,
        applyChanges: analysis.applyChanges,
    };

    // Show floating status when analysis is active but modal is closed
    const showFloating = !modalOpen && (isActive || needsReview);

    return (
        <AnalysisContext.Provider value={value}>
            {children}
            <AnalyzeModal open={modalOpen} onOpenChange={handleModalChange} />
            {showFloating && (
                <AnalysisFloatingStatus
                    status={analysis.status}
                    progress={analysis.progress}
                    total={analysis.total}
                    changesCount={analysis.changesCount}
                    currentTrack={analysis.currentTrack}
                    onOpen={openModal}
                    onPause={analysis.pause}
                    onResume={analysis.resume}
                />
            )}
        </AnalysisContext.Provider>
    );
}

