                                                const padKey = `${activeTrackProfile.midiChannel}:${noteNum}`;
                                                const isActive = activePads.has(padKey);
                                                const noteNames = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
