                                                "text-[5px] font-bold w-full py-0.5 rounded cursor-pointer transition-all text-center",
                                                ts?.muted ? "bg-red-500/20 text-red-400" : "bg-white/5 text-white/20 hover:bg-white/10"
                                            )}
                                        >
