// ΓöÇΓöÇ Greeting ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function getGreeting() {
    const h = new Date().getHours();
    if (h >= 5 && h < 12) return { text: "Good morning", emoji: "≡ƒîà" };
    if (h >= 12 && h < 18) return { text: "Good afternoon", emoji: "ΓÿÇ∩╕Å" };
    if (h >= 18 && h < 22) return { text: "Good evening", emoji: "≡ƒîå" };
    return { text: "Night owl mode", emoji: "≡ƒîÖ" };
}

function formatTotalDuration(seconds: number) {
    if (!seconds) return "0h";
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h === 0) return `${m}m`;
    return `${h}h ${m}m`;
}

