                            clips: t.clips.map(c => c.id !== clipId || !c.audio ? c : {
                                ...c,
                                name: file.name,
                                audio: {
                                    ...c.audio,
                                    buffer,
                                    sourceUrl: url,
                                    name: file.name,
                                    duration: buffer.duration,
                                    waveformPeaks: peaks,
                                },
