    const moveAutomationPoint = useCallback((laneId: string, pointIndex: number, time: number, value: number) => {
        updateProject(p => ({
            ...p,
            tracks: p.tracks.map(t => ({
                ...t,
                automationLanes: t.automationLanes.map(l =>
                    l.id === laneId ? {
                        ...l,
