interface EditorContextValue {
    // Project
    project: EditorProject;
    isLoading: boolean;
    error: string | null;

    // Audio buffer
    buffer: AudioBuffer | null;
    peaks: Float32Array | null;

    // View
    view: EditorView;
    setView: (v: EditorView) => void;
    zoom: number; // pixels per second
    setZoom: (z: number) => void;
    scrollX: number; // seconds
    setScrollX: (x: number) => void;

    // Tool
    tool: EditorTool;
    setTool: (t: EditorTool) => void;

    // Selection
    selection: Selection | null;
    setSelection: (s: Selection | null) => void;

    // Playback
    isPlaying: boolean;
    playPosition: number; // seconds
    play: () => void;
    pause: () => void;
    stop: () => void;
    seek: (pos: number) => void;

    // Markers & Regions
    addMarker: (position: number, label?: string) => void;
    removeMarker: (id: string) => void;
    addRegion: (start: number, end: number, label?: string) => void;
    removeRegion: (id: string) => void;

    // Editing
    cut: () => void;
    copy: () => void;
    paste: () => void;
    deleteSelection: () => void;
    normalize: () => void;
    fadeIn: (duration?: number) => void;
    fadeOut: (duration?: number) => void;
    reverse: () => void;
    silence: () => void;

    // Undo/Redo
    undo: () => void;
    redo: () => void;
    canUndo: boolean;
    canRedo: boolean;
    history: HistoryState<EditorSnapshot>;
    jumpToHistoryEntry: (index: number) => void;

    // Load
    loadFromUrl: (url: string, name?: string) => Promise<void>;
    loadFromFile: (file: File) => Promise<void>;

    // Recording
    isRecording: boolean;
    startRecording: (deviceId?: string) => Promise<boolean>;
    stopRecording: () => void;

    // Stems
    isSeparatingStems: boolean;
    stemsProgress: number;
    separateStems: () => Promise<void>;
    extractStem: (stem: import("@/lib/stems-engine").StemType) => Promise<void>;

    // Levels
    peakL: number;
    peakR: number;
}

const EditorContext = createContext<EditorContextValue | null>(null);

export function useEditor(): EditorContextValue {
    const ctx = useContext(EditorContext);
    if (!ctx) throw new Error("useEditor must be used within EditorProvider");
    return ctx;
}

