// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

const DEFAULT_PROJECT: EditorProject = {
    id: "",
    name: "Untitled",
    sourceUrl: "",
    sampleRate: 44100,
    channels: 2,
    duration: 0,
    markers: [],
    regions: [],
    editHistory: [],
};

export function EditorProvider({ children }: { children: ReactNode }) {
    useRenderCount("EditorProvider");
    const [project, setProject] = useState<EditorProject>(DEFAULT_PROJECT);
    const [buffer, setBuffer] = useState<AudioBuffer | null>(null);
    const [peaks, setPeaks] = useState<Float32Array | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // View
    const [view, setView] = useState<EditorView>("waveform");
    const [zoom, setZoom] = useState(100); // px per second
    const [scrollX, setScrollX] = useState(0);

    // Tool
    const [tool, setTool] = useState<EditorTool>("select");

    // Selection
    const [selection, setSelection] = useState<Selection | null>(null);

    // Playback
    const [isPlaying, setIsPlaying] = useState(false);
    const [playPosition, setPlayPosition] = useState(0);
    const [peakL, setPeakL] = useState(0);
    const [peakR, setPeakR] = useState(0);
    const audioCtxRef = useRef<AudioContext | null>(null);
    const sourceRef = useRef<AudioBufferSourceNode | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const startTimeRef = useRef(0);
    const offsetRef = useRef(0);
    const rafRef = useRef(0);

    // History (undo/redo)
    const [history, setHistory] = useState<HistoryState<EditorSnapshot>>(() =>
        createHistory<EditorSnapshot>({ buffer: null as unknown as AudioBuffer, markers: [], regions: [] }, "Initial", 50)
    );

    // Clipboard
    const clipboardRef = useRef<AudioBuffer | null>(null);

    // ΓöÇΓöÇΓöÇ Audio context ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const getAudioCtx = useCallback(() => {
        if (!audioCtxRef.current) {
            audioCtxRef.current = new AudioContext();
        }
        return audioCtxRef.current;
    }, []);

    // ΓöÇΓöÇΓöÇ Playback animation loop ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const updatePlayPosition = useCallback(() => {
        const ctx = audioCtxRef.current;
        if (!ctx || !isPlaying) return;
        const pos = ctx.currentTime - startTimeRef.current + offsetRef.current;
        setPlayPosition(pos);

        // Level metering
        if (analyserRef.current) {
            const data = new Float32Array(analyserRef.current.fftSize);
            analyserRef.current.getFloatTimeDomainData(data);
            let max = 0;
            for (let i = 0; i < data.length; i++) {
                const abs = Math.abs(data[i]);
                if (abs > max) max = abs;
            }
            setPeakL(max);
            setPeakR(max);
        }

        rafRef.current = requestAnimationFrame(updatePlayPosition);
    }, [isPlaying]);

    useEffect(() => {
        if (isPlaying) {
            rafRef.current = requestAnimationFrame(updatePlayPosition);
        }
        return () => cancelAnimationFrame(rafRef.current);
    }, [isPlaying, updatePlayPosition]);

    // ΓöÇΓöÇΓöÇ Push named undo ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const pushUndoNamed = useCallback((label: string, icon?: string) => {
        if (!buffer) return;
        setHistory(prev => pushHistory(prev, { buffer, markers: project.markers, regions: project.regions }, label, icon));
    }, [buffer, project.markers, project.regions]);

    // ΓöÇΓöÇΓöÇ Load audio ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const loadBuffer = useCallback((buf: AudioBuffer, name: string, url: string = "") => {
        setBuffer(buf);
        setPeaks(computePeaks(buf, Math.min(4000, buf.length)));
        setProject(p => ({
            ...p,
            id: createId(),
            name,
            sourceUrl: url,
            sampleRate: buf.sampleRate,
            channels: buf.numberOfChannels,
            duration: buf.duration,
        }));
        setScrollX(0);
        setPlayPosition(0);
        setHistory(createHistory<EditorSnapshot>({ buffer: buf, markers: [], regions: [] }, `Loaded "${name}"`, 50));
        setError(null);
    }, []);

    const loadFromUrl = useCallback(async (url: string, name?: string) => {
        setIsLoading(true);
        setError(null);
        try {
            const ctx = getAudioCtx();
            const res = await fetch(url);
            if (!res.ok) throw new Error(`Failed to load: ${res.status}`);
            const arrayBuf = await res.arrayBuffer();
            const audioBuf = await ctx.decodeAudioData(arrayBuf);
            loadBuffer(audioBuf, name || url.split("/").pop() || "Audio", url);
        } catch (e) {
            setError(e instanceof Error ? e.message : "Failed to load audio");
        } finally {
            setIsLoading(false);
        }
    }, [getAudioCtx, loadBuffer]);

    const loadFromFile = useCallback(async (file: File) => {
        setIsLoading(true);
        setError(null);
        try {
            const ctx = getAudioCtx();
            const arrayBuf = await file.arrayBuffer();
            const audioBuf = await ctx.decodeAudioData(arrayBuf);
            loadBuffer(audioBuf, file.name);
        } catch (e) {
            setError(e instanceof Error ? e.message : "Failed to decode audio file");
        } finally {
            setIsLoading(false);
        }
    }, [getAudioCtx, loadBuffer]);

    // ΓöÇΓöÇΓöÇ Recording ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [isRecording, setIsRecording] = useState(false);
    const recorderRef = useRef<MediaRecorder | null>(null);
    const recChunksRef = useRef<Blob[]>([]);
    const recStreamRef = useRef<MediaStream | null>(null);

    // Stems
    const [isSeparatingStems, setIsSeparatingStems] = useState(false);
    const [stemsProgress, setStemsProgress] = useState(0);

    const startRecording = useCallback(async (deviceId?: string): Promise<boolean> => {
        try {
            const ctx = getAudioCtx();
            if (ctx.state === "suspended") await ctx.resume();

            // Stop playback if playing
            if (sourceRef.current) {
                sourceRef.current.onended = null;
                try { sourceRef.current.stop(); } catch { /* noop */ }
            }
            setIsPlaying(false);

            const constraints: MediaStreamConstraints = {
                audio: deviceId ? { deviceId: { exact: deviceId } } : true,
            };
            const stream = await navigator.mediaDevices.getUserMedia(constraints);
            recStreamRef.current = stream;

            // Route through AudioContext so we can capture at correct sample rate
            const source = ctx.createMediaStreamSource(stream);
            const dest = ctx.createMediaStreamDestination();
            source.connect(dest);

            const recorder = new MediaRecorder(dest.stream, {
                mimeType: MediaRecorder.isTypeSupported("audio/webm;codecs=opus")
                    ? "audio/webm;codecs=opus"
                    : "audio/webm",
            });

            recChunksRef.current = [];
            recorder.ondataavailable = (e) => {
                if (e.data.size > 0) recChunksRef.current.push(e.data);
            };

            recorder.onstop = async () => {
                // Cleanup mic stream
                recStreamRef.current?.getTracks().forEach(t => t.stop());
                recStreamRef.current = null;
                source.disconnect();

                if (recChunksRef.current.length === 0) return;

                const blob = new Blob(recChunksRef.current, { type: recorder.mimeType });
                recChunksRef.current = [];

                try {
                    const arrayBuf = await blob.arrayBuffer();
                    const audioBuf = await ctx.decodeAudioData(arrayBuf);
                    loadBuffer(audioBuf, "Recording");
                } catch (e) {
                    setError(e instanceof Error ? e.message : "Failed to decode recording");
                }
            };

            recorder.start(250); // Collect data every 250ms
            recorderRef.current = recorder;
            setIsRecording(true);
            return true;
        } catch (e) {
            setError(e instanceof Error ? e.message : "Failed to start recording");
            return false;
        }
    }, [getAudioCtx, loadBuffer]);

    const stopRecording = useCallback(() => {
        if (recorderRef.current && recorderRef.current.state !== "inactive") {
            recorderRef.current.stop();
        }
        recorderRef.current = null;
        setIsRecording(false);
    }, []);

    // ΓöÇΓöÇΓöÇ Playback controls ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const play = useCallback(() => {
        if (!buffer) return;
        const ctx = getAudioCtx();
        if (ctx.state === "suspended") ctx.resume();

        // Stop existing
        if (sourceRef.current) {
            sourceRef.current.onended = null;
            sourceRef.current.stop();
        }

        const analyser = ctx.createAnalyser();
        analyser.fftSize = 2048;
        analyserRef.current = analyser;

        const src = ctx.createBufferSource();
        src.buffer = buffer;
        src.connect(analyser);
        analyser.connect(ctx.destination);

        const offset = playPosition >= buffer.duration ? 0 : playPosition;
        offsetRef.current = offset;
        startTimeRef.current = ctx.currentTime;
        src.start(0, offset);
        sourceRef.current = src;
        setIsPlaying(true);

        src.onended = () => {
            setIsPlaying(false);
            setPlayPosition(0);
        };
    }, [buffer, getAudioCtx, playPosition]);

    const pause = useCallback(() => {
        if (sourceRef.current) {
            sourceRef.current.onended = null;
            sourceRef.current.stop();
        }
        const ctx = audioCtxRef.current;
        if (ctx) {
            setPlayPosition(ctx.currentTime - startTimeRef.current + offsetRef.current);
        }
        setIsPlaying(false);
    }, []);

    const stop = useCallback(() => {
        if (isRecording) {
            stopRecording();
        }
        if (sourceRef.current) {
            sourceRef.current.onended = null;
            sourceRef.current.stop();
        }
        setIsPlaying(false);
        setPlayPosition(0);
    }, [isRecording, stopRecording]);

    // ΓöÇΓöÇΓöÇ Stems ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    const separateStems = useCallback(async () => {
        if (!buffer || isSeparatingStems) return;
        setIsSeparatingStems(true);
        setStemsProgress(0);
        try {
            const { separateStems: runStemSep, STEM_LABELS } = await import("@/lib/stems-engine");
            setStemsProgress(25);
            const result = await runStemSep(buffer);
            setStemsProgress(100);

            // Store stems for extractStem to use
            (window as unknown as Record<string, unknown>).__editorStems = result;
        } finally {
            setIsSeparatingStems(false);
        }
    }, [buffer, isSeparatingStems]);

    const extractStem = useCallback(async (stemType: import("@/lib/stems-engine").StemType) => {
        const stems = (window as unknown as Record<string, unknown>).__editorStems as Record<string, AudioBuffer> | undefined;
        if (!stems || !stems[stemType]) {
            // If no cached stems, separate first
            if (!buffer) return;
            setIsSeparatingStems(true);
            setStemsProgress(0);
            try {
                const { separateStems: runStemSep } = await import("@/lib/stems-engine");
                setStemsProgress(25);
                const result = await runStemSep(buffer);
                setStemsProgress(100);
                (window as unknown as Record<string, unknown>).__editorStems = result;
                const stemBuf = result[stemType];
                if (stemBuf) {
                    pushUndoNamed(`Extract ${stemType}`, "Layers");
                    loadBuffer(stemBuf, `${stemType} stem`);
                }
            } finally {
                setIsSeparatingStems(false);
            }
            return;
        }
        const stemBuf = stems[stemType] as AudioBuffer;
        if (stemBuf) {
            pushUndoNamed(`Extract ${stemType}`, "Layers");
            loadBuffer(stemBuf, `${stemType} stem`);
        }
    }, [buffer, loadBuffer, pushUndoNamed]);

    const seek = useCallback((pos: number) => {
        setPlayPosition(Math.max(0, pos));
        if (isPlaying) {
            // Restart from new position
            pause();
            setTimeout(() => {
                offsetRef.current = pos;
                play();
            }, 10);
        }
    }, [isPlaying, pause, play]);

    // ΓöÇΓöÇΓöÇ Markers & Regions ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const addMarker = useCallback((position: number, label?: string) => {
        setProject(p => ({
            ...p,
            markers: [...p.markers, { id: createId(), position, label: label || `M${p.markers.length + 1}`, color: "#f59e0b" }],
        }));
    }, []);

    const removeMarker = useCallback((id: string) => {
        setProject(p => ({ ...p, markers: p.markers.filter(m => m.id !== id) }));
    }, []);

    const addRegion = useCallback((start: number, end: number, label?: string) => {
        setProject(p => ({
            ...p,
            regions: [...p.regions, { id: createId(), start, end, label: label || `R${p.regions.length + 1}`, color: "#3b82f6" }],
        }));
    }, []);

    const removeRegion = useCallback((id: string) => {
        setProject(p => ({ ...p, regions: p.regions.filter(r => r.id !== id) }));
    }, []);

    // ΓöÇΓöÇΓöÇ Buffer editing helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const applyBufferEdit = useCallback((newBuf: AudioBuffer) => {
        setBuffer(newBuf);
        setPeaks(computePeaks(newBuf, Math.min(4000, newBuf.length)));
        setProject(p => ({ ...p, duration: newBuf.duration }));
    }, []);

    // ΓöÇΓöÇΓöÇ Cut / Copy / Paste / Delete ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const cut = useCallback(() => {
        if (!buffer || !selection) return;
        pushUndoNamed("Cut Selection", "Scissors");
        const ctx = getAudioCtx();
        clipboardRef.current = sliceBuffer(ctx, buffer, selection.start, selection.end);
        const before = sliceBuffer(ctx, buffer, 0, selection.start);
        const after = sliceBuffer(ctx, buffer, selection.end, buffer.duration);
        applyBufferEdit(concatBuffers(before, after));
        setSelection(null);
    }, [buffer, selection, pushUndoNamed, getAudioCtx, applyBufferEdit]);

    const copy = useCallback(() => {
        if (!buffer || !selection) return;
        const ctx = getAudioCtx();
        clipboardRef.current = sliceBuffer(ctx, buffer, selection.start, selection.end);
    }, [buffer, selection, getAudioCtx]);

    const paste = useCallback(() => {
        if (!buffer || !clipboardRef.current) return;
        pushUndoNamed("Paste Audio", "Clipboard");
        const ctx = getAudioCtx();
        const insertAt = selection?.start ?? playPosition;
        const before = sliceBuffer(ctx, buffer, 0, insertAt);
        const after = sliceBuffer(ctx, buffer, insertAt, buffer.duration);
        const combined = concatBuffers(concatBuffers(before, clipboardRef.current), after);
        applyBufferEdit(combined);
    }, [buffer, selection, playPosition, pushUndoNamed, getAudioCtx, applyBufferEdit]);

    const deleteSelection = useCallback(() => {
        if (!buffer || !selection) return;
        pushUndoNamed("Delete Selection", "Trash2");
        const ctx = getAudioCtx();
        const before = sliceBuffer(ctx, buffer, 0, selection.start);
        const after = sliceBuffer(ctx, buffer, selection.end, buffer.duration);
        applyBufferEdit(concatBuffers(before, after));
        setSelection(null);
    }, [buffer, selection, pushUndoNamed, getAudioCtx, applyBufferEdit]);

    // ΓöÇΓöÇΓöÇ Normalize ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const normalize = useCallback(() => {
        if (!buffer) return;
        pushUndoNamed("Normalize", "Volume2");
        const newBuf = new AudioBuffer({
            numberOfChannels: buffer.numberOfChannels,
            length: buffer.length,
            sampleRate: buffer.sampleRate,
        });
        let globalMax = 0;
        for (let ch = 0; ch < buffer.numberOfChannels; ch++) {
            const data = buffer.getChannelData(ch);
            for (let i = 0; i < data.length; i++) {
                const abs = Math.abs(data[i]);
                if (abs > globalMax) globalMax = abs;
            }
        }
        const gain = globalMax > 0 ? 1 / globalMax : 1;
        for (let ch = 0; ch < buffer.numberOfChannels; ch++) {
            const src = buffer.getChannelData(ch);
            const dest = newBuf.getChannelData(ch);
            for (let i = 0; i < src.length; i++) {
                dest[i] = src[i] * gain;
            }
        }
        applyBufferEdit(newBuf);
    }, [buffer, pushUndoNamed, applyBufferEdit]);

    // ΓöÇΓöÇΓöÇ Fade In / Out ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const fadeInFn = useCallback((duration = 0.5) => {
        if (!buffer) return;
        pushUndoNamed(`Fade In (${duration}s)`, "ArrowUpFromLine");
        const newBuf = new AudioBuffer({
            numberOfChannels: buffer.numberOfChannels,
            length: buffer.length,
            sampleRate: buffer.sampleRate,
        });
        const fadeSamples = Math.floor(duration * buffer.sampleRate);
        for (let ch = 0; ch < buffer.numberOfChannels; ch++) {
            const src = buffer.getChannelData(ch);
            const dest = newBuf.getChannelData(ch);
            for (let i = 0; i < src.length; i++) {
                const g = i < fadeSamples ? i / fadeSamples : 1;
                dest[i] = src[i] * g;
            }
        }
        applyBufferEdit(newBuf);
    }, [buffer, pushUndoNamed, applyBufferEdit]);

    const fadeOutFn = useCallback((duration = 0.5) => {
        if (!buffer) return;
        pushUndoNamed(`Fade Out (${duration}s)`, "ArrowDownToLine");
        const newBuf = new AudioBuffer({
            numberOfChannels: buffer.numberOfChannels,
            length: buffer.length,
            sampleRate: buffer.sampleRate,
        });
        const fadeSamples = Math.floor(duration * buffer.sampleRate);
        const fadeStart = buffer.length - fadeSamples;
        for (let ch = 0; ch < buffer.numberOfChannels; ch++) {
            const src = buffer.getChannelData(ch);
            const dest = newBuf.getChannelData(ch);
            for (let i = 0; i < src.length; i++) {
                const g = i > fadeStart ? (buffer.length - i) / fadeSamples : 1;
                dest[i] = src[i] * g;
            }
        }
        applyBufferEdit(newBuf);
    }, [buffer, pushUndoNamed, applyBufferEdit]);

    // ΓöÇΓöÇΓöÇ Reverse ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const reverseFn = useCallback(() => {
        if (!buffer) return;
        pushUndoNamed("Reverse", "RotateCcw");
        const newBuf = new AudioBuffer({
            numberOfChannels: buffer.numberOfChannels,
            length: buffer.length,
            sampleRate: buffer.sampleRate,
        });
        for (let ch = 0; ch < buffer.numberOfChannels; ch++) {
            const src = buffer.getChannelData(ch);
            const dest = newBuf.getChannelData(ch);
            for (let i = 0; i < src.length; i++) {
                dest[i] = src[src.length - 1 - i];
            }
        }
        applyBufferEdit(newBuf);
    }, [buffer, pushUndoNamed, applyBufferEdit]);

    // ΓöÇΓöÇΓöÇ Silence ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const silenceFn = useCallback(() => {
        if (!buffer || !selection) return;
        pushUndoNamed("Silence Selection", "VolumeX");
        const newBuf = new AudioBuffer({
            numberOfChannels: buffer.numberOfChannels,
            length: buffer.length,
            sampleRate: buffer.sampleRate,
        });
        const startSample = Math.floor(selection.start * buffer.sampleRate);
        const endSample = Math.floor(selection.end * buffer.sampleRate);
        for (let ch = 0; ch < buffer.numberOfChannels; ch++) {
            const src = buffer.getChannelData(ch);
            const dest = newBuf.getChannelData(ch);
            for (let i = 0; i < src.length; i++) {
                dest[i] = (i >= startSample && i < endSample) ? 0 : src[i];
            }
        }
        applyBufferEdit(newBuf);
    }, [buffer, selection, pushUndoNamed, applyBufferEdit]);

    // ΓöÇΓöÇΓöÇ Undo / Redo ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const undo = useCallback(() => {
        if (!histCanUndo(history) || !buffer) return;
        // Save current state as future before jumping back
        const newHistory = undoHistory(history);
        const snapshot = getCurrentSnapshot(newHistory);
        setHistory(newHistory);
        setBuffer(snapshot.buffer);
        setPeaks(computePeaks(snapshot.buffer, Math.min(4000, snapshot.buffer.length)));
        setProject(p => ({ ...p, duration: snapshot.buffer.duration, markers: snapshot.markers, regions: snapshot.regions }));
    }, [history, buffer]);

    const redo = useCallback(() => {
        if (!histCanRedo(history) || !buffer) return;
        const newHistory = redoHistory(history);
        const snapshot = getCurrentSnapshot(newHistory);
        setHistory(newHistory);
        setBuffer(snapshot.buffer);
        setPeaks(computePeaks(snapshot.buffer, Math.min(4000, snapshot.buffer.length)));
        setProject(p => ({ ...p, duration: snapshot.buffer.duration, markers: snapshot.markers, regions: snapshot.regions }));
    }, [history, buffer]);

    const jumpToHistoryEntry = useCallback((index: number) => {
        const newHistory = jumpToHistory(history, index);
        const snapshot = getCurrentSnapshot(newHistory);
        setHistory(newHistory);
        setBuffer(snapshot.buffer);
        setPeaks(computePeaks(snapshot.buffer, Math.min(4000, snapshot.buffer.length)));
        setProject(p => ({ ...p, duration: snapshot.buffer.duration, markers: snapshot.markers, regions: snapshot.regions }));
    }, [history]);

    // ΓöÇΓöÇΓöÇ Cleanup ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    useEffect(() => {
        return () => {
            cancelAnimationFrame(rafRef.current);
            if (recorderRef.current && recorderRef.current.state !== "inactive") {
                recorderRef.current.stop();
            }
            recStreamRef.current?.getTracks().forEach(t => t.stop());
            if (sourceRef.current) {
                sourceRef.current.onended = null;
                try { sourceRef.current.stop(); } catch { /* already stopped */ }
            }
            if (audioCtxRef.current?.state !== "closed") {
                audioCtxRef.current?.close();
            }
        };
    }, []);

    const value: EditorContextValue = {
        project, isLoading, error,
        buffer, peaks,
        view, setView, zoom, setZoom, scrollX, setScrollX,
        tool, setTool,
        selection, setSelection,
        isPlaying, playPosition, play, pause, stop, seek,
        addMarker, removeMarker, addRegion, removeRegion,
        cut, copy, paste, deleteSelection, normalize,
        fadeIn: fadeInFn, fadeOut: fadeOutFn,
        reverse: reverseFn, silence: silenceFn,
        undo, redo,
        canUndo: histCanUndo(history),
        canRedo: histCanRedo(history),
        history, jumpToHistoryEntry,
        loadFromUrl, loadFromFile,
        isRecording, startRecording, stopRecording,
        isSeparatingStems, stemsProgress, separateStems, extractStem,
        peakL, peakR,
    };

    return (
        <EditorContext value={value}>
            {children}
        </EditorContext>
    );
}

