"use client";

import { useRef, useEffect, useCallback, useState } from "react";
import { useEditor } from "./editor-context";
import { useDAWSettings, type SpectrogramColorMap } from "@/hooks/use-daw-settings";
import { useRenderCount } from "@/lib/dev-debugger";

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// Spectrogram View ΓÇö FFT-based frequency visualization
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

const DEFAULT_FFT_SIZE = 2048;

const COLOR_MAPS: Record<SpectrogramColorMap, number[][]> = {
    magma: [
        [0, 0, 0], [15, 5, 50], [40, 10, 100], [80, 20, 160],
        [20, 80, 200], [20, 180, 200], [80, 220, 100],
        [220, 220, 50], [255, 140, 20], [255, 40, 40], [255, 255, 255],
    ],
    viridis: [
        [68, 1, 84], [72, 35, 116], [64, 67, 135], [52, 94, 141],
        [33, 145, 140], [53, 183, 121], [109, 205, 89],
        [180, 222, 44], [253, 231, 37], [253, 231, 37], [255, 255, 255],
    ],
    inferno: [
        [0, 0, 4], [22, 11, 57], [66, 10, 104], [120, 28, 109],
        [165, 44, 96], [207, 68, 70], [237, 105, 37],
        [251, 155, 6], [252, 206, 37], [252, 255, 164], [255, 255, 255],
    ],
    plasma: [
        [13, 8, 135], [75, 3, 161], [126, 3, 168], [168, 34, 150],
        [203, 70, 121], [229, 107, 93], [248, 148, 65],
        [253, 195, 40], [240, 249, 33], [240, 249, 33], [255, 255, 255],
    ],
    grayscale: [
        [0, 0, 0], [25, 25, 25], [51, 51, 51], [76, 76, 76],
        [102, 102, 102], [127, 127, 127], [153, 153, 153],
        [178, 178, 178], [204, 204, 204], [229, 229, 229], [255, 255, 255],
    ],
};

function buildColorLUT(colorMap: SpectrogramColorMap): Uint8Array {
    const stops = COLOR_MAPS[colorMap];
    const lut = new Uint8Array(256 * 3);
    for (let i = 0; i < 256; i++) {
        const amplitude = i / 255;
        const idx = amplitude * (stops.length - 1);
        const lo = Math.floor(idx);
        const hi = Math.min(lo + 1, stops.length - 1);
        const t = idx - lo;
        lut[i * 3] = stops[lo][0] + (stops[hi][0] - stops[lo][0]) * t;
        lut[i * 3 + 1] = stops[lo][1] + (stops[hi][1] - stops[lo][1]) * t;
        lut[i * 3 + 2] = stops[lo][2] + (stops[hi][2] - stops[lo][2]) * t;
    }
    return lut;
}

// Pre-computed LUT cache
const lutCache = new Map<SpectrogramColorMap, Uint8Array>();
function getColorLUT(colorMap: SpectrogramColorMap): Uint8Array {
    if (!lutCache.has(colorMap)) {
        lutCache.set(colorMap, buildColorLUT(colorMap));
    }
    return lutCache.get(colorMap)!;
}

export function SpectrogramView() {
    useRenderCount("SpectrogramView");
    const editor = useEditor();
    const ds = useDAWSettings();
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [dimensions, setDimensions] = useState({ width: 800, height: 300 });

    // Resize observer
    useEffect(() => {
        const el = containerRef.current;
        if (!el) return;
        const obs = new ResizeObserver(entries => {
            for (const entry of entries) {
                setDimensions({
                    width: entry.contentRect.width,
                    height: entry.contentRect.height,
                });
            }
        });
        obs.observe(el);
        return () => obs.disconnect();
    }, []);

    // Render spectrogram
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas || !editor.buffer) return;

        const ctx = canvas.getContext("2d");
        if (!ctx) return;

        const dpr = window.devicePixelRatio || 1;
        const w = dimensions.width;
        const h = dimensions.height;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        ctx.scale(dpr, dpr);

        const { buffer, scrollX, zoom, selection, playPosition } = editor;
        const sampleRate = buffer.sampleRate;
        const data = buffer.getChannelData(0); // mono for spectrogram
        const fftSize = ds.spectrogramFftSize;
        const halfFFT = fftSize / 2;
        const colorLUT = getColorLUT(ds.spectrogramColorMap);

        // Clear
        ctx.fillStyle = "#000";
        ctx.fillRect(0, 0, w, h);

        // Compute FFT for each pixel column
        const imageData = ctx.createImageData(w, h);
        const pixels = imageData.data;

        // Hann window
        const hannWindow = new Float32Array(fftSize);
        for (let i = 0; i < fftSize; i++) {
            hannWindow[i] = 0.5 * (1 - Math.cos((2 * Math.PI * i) / (fftSize - 1)));
        }

        for (let px = 0; px < w; px++) {
            const timeSec = scrollX + px / zoom;
            const centerSample = Math.floor(timeSec * sampleRate);

            // Extract windowed segment
            const segment = new Float32Array(fftSize);
            for (let i = 0; i < fftSize; i++) {
                const sampleIdx = centerSample - halfFFT + i;
                segment[i] = (sampleIdx >= 0 && sampleIdx < data.length ? data[sampleIdx] : 0) * hannWindow[i];
            }

            // Simple DFT (real FFT approximation using only magnitude)
            // For performance, we only compute halfFFT bins
            const magnitudes = new Float32Array(halfFFT);
            let maxMag = 0;

            for (let k = 0; k < halfFFT; k++) {
                let real = 0;
                let imag = 0;
                for (let n = 0; n < fftSize; n++) {
                    const angle = (-2 * Math.PI * k * n) / fftSize;
                    real += segment[n] * Math.cos(angle);
                    imag += segment[n] * Math.sin(angle);
                }
                magnitudes[k] = Math.sqrt(real * real + imag * imag) / fftSize;
                if (magnitudes[k] > maxMag) maxMag = magnitudes[k];
            }

            // Draw column (frequency bins ΓåÆ pixels, low freq at bottom)
            for (let y = 0; y < h; y++) {
                const freqBin = Math.floor(((h - 1 - y) / h) * halfFFT);
                const mag = magnitudes[freqBin];
                // Log scale for better visualization
                const dbNorm = maxMag > 0
                    ? Math.max(0, Math.min(1, (20 * Math.log10(mag / maxMag) + 80) / 80))
                    : 0;
                const colorIdx = Math.floor(dbNorm * 255);
                const pixelIdx = (y * w + px) * 4;
                pixels[pixelIdx] = colorLUT[colorIdx * 3];
                pixels[pixelIdx + 1] = colorLUT[colorIdx * 3 + 1];
                pixels[pixelIdx + 2] = colorLUT[colorIdx * 3 + 2];
                pixels[pixelIdx + 3] = 255;
            }
        }

        ctx.putImageData(imageData, 0, 0);

        // Selection overlay
        if (selection) {
            const selLeft = (selection.start - scrollX) * zoom;
            const selWidth = (selection.end - selection.start) * zoom;
            ctx.fillStyle = "oklch(0.62 0.19 250 / 0.15)";
            ctx.fillRect(selLeft, 0, selWidth, h);
            ctx.strokeStyle = "oklch(0.62 0.19 250 / 0.5)";
            ctx.lineWidth = 1;
            ctx.strokeRect(selLeft, 0, selWidth, h);
        }

        // Playhead
        const phx = (playPosition - scrollX) * zoom;
        if (phx >= 0 && phx <= w) {
            ctx.strokeStyle = "#22c55e";
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(phx, 0);
            ctx.lineTo(phx, h);
            ctx.stroke();
        }

        // Frequency labels
        ctx.fillStyle = "oklch(1 0 0 / 0.3)";
        ctx.font = "9px monospace";
        const freqLabels = [100, 500, 1000, 2000, 5000, 10000, 20000];
        const nyquist = sampleRate / 2;
        for (const freq of freqLabels) {
            if (freq > nyquist) continue;
            const y = h - (freq / nyquist) * h;
            ctx.fillText(`${freq >= 1000 ? `${freq / 1000}k` : freq}Hz`, 4, y - 2);
            ctx.strokeStyle = "oklch(1 0 0 / 0.06)";
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(w, y);
            ctx.stroke();
        }
    }, [editor.buffer, editor.scrollX, editor.zoom, editor.selection, editor.playPosition, dimensions, ds.spectrogramColorMap, ds.spectrogramFftSize]);

    // Mouse handlers (same as waveform for selection)
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState<number | null>(null);

    const pxToSeconds = useCallback((clientX: number): number => {
        const canvas = canvasRef.current;
        if (!canvas) return 0;
        const rect = canvas.getBoundingClientRect();
        const x = clientX - rect.left;
        return editor.scrollX + x / editor.zoom;
    }, [editor.scrollX, editor.zoom]);

    const handleMouseDown = useCallback((e: React.MouseEvent) => {
        if (e.button !== 0) return;
        const sec = pxToSeconds(e.clientX);
        if (editor.tool === "select") {
            setIsDragging(true);
            setDragStart(sec);
            editor.setSelection(null);
        }
    }, [editor, pxToSeconds]);

    const handleMouseMove = useCallback((e: React.MouseEvent) => {
        if (!isDragging || dragStart === null) return;
        const sec = pxToSeconds(e.clientX);
        editor.setSelection({
            start: Math.min(dragStart, sec),
            end: Math.max(dragStart, sec),
        });
    }, [isDragging, dragStart, editor, pxToSeconds]);

    const handleMouseUp = useCallback(() => {
        setIsDragging(false);
        setDragStart(null);
    }, []);

    const handleWheel = useCallback((e: React.WheelEvent) => {
        if (e.ctrlKey) {
            e.preventDefault();
            const factor = e.deltaY > 0 ? 0.9 : 1.1;
            editor.setZoom(Math.max(10, Math.min(5000, editor.zoom * factor)));
        } else {
            const scrollDelta = e.deltaX !== 0 ? e.deltaX : e.deltaY;
            editor.setScrollX(Math.max(0, editor.scrollX + scrollDelta / editor.zoom));
        }
    }, [editor]);

    return (
        <div ref={containerRef} className="relative w-full h-full overflow-hidden bg-black">
            <canvas
                ref={canvasRef}
                className="w-full h-full"
                style={{ cursor: editor.tool === "select" ? "text" : "default" }}
                onMouseDown={handleMouseDown}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
                onWheel={handleWheel}
            />
        </div>
    );
}

"use client";

import { useRef, useEffect, useCallback, useState } from "react";
import { useEditor } from "./editor-context";
import { cn } from "@/lib/utils";
import { useRenderCount } from "@/lib/dev-debugger";
import { useDAWSettings, EDITOR_WAVEFORM_COLORS } from "@/hooks/use-daw-settings";

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// Waveform View ΓÇö Canvas-based zoomable waveform
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

export function WaveformView() {
    useRenderCount("WaveformView");
    const editor = useEditor();
    const ds = useDAWSettings();
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [dimensions, setDimensions] = useState({ width: 800, height: 300 });
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState<number | null>(null);

    // Resize observer
    useEffect(() => {
        const el = containerRef.current;
        if (!el) return;
        const obs = new ResizeObserver(entries => {
            for (const entry of entries) {
                setDimensions({
                    width: entry.contentRect.width,
                    height: entry.contentRect.height,
                });
            }
        });
        obs.observe(el);
        return () => obs.disconnect();
    }, []);

    // ΓöÇΓöÇΓöÇ Draw waveform ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas || !editor.buffer) return;

        const ctx = canvas.getContext("2d");
        if (!ctx) return;

        const dpr = window.devicePixelRatio || 1;
        canvas.width = dimensions.width * dpr;
        canvas.height = dimensions.height * dpr;
        ctx.scale(dpr, dpr);

        const { width, height } = dimensions;
        const { buffer, scrollX, zoom, selection, playPosition } = editor;
        const channels = buffer.numberOfChannels;
        const channelHeight = height / channels;

        // Clear
        ctx.fillStyle = "oklch(0.14 0.01 260)";
        ctx.fillRect(0, 0, width, height);

        const waveColor = ds.editorWaveformHex;
        // Extract oklch base values for alpha variants
        const waveColorMatch = waveColor.match(/oklch\(([^)]+)\)/);
        const waveBase = waveColorMatch ? waveColorMatch[1] : "0.62 0.19 250";
        const waveColor06 = `oklch(${waveBase} / 0.6)`;
        const waveColor03 = `oklch(${waveBase} / 0.3)`;
        const waveColor015 = `oklch(${waveBase} / 0.15)`;
        const waveColor05 = `oklch(${waveBase} / 0.5)`;

        // Draw grid lines (every 0.5s)
        if (ds.editorShowGridLines) {
            ctx.strokeStyle = "oklch(1 0 0 / 0.04)";
            ctx.lineWidth = 1;
            const startSec = scrollX;
            const endSec = scrollX + width / zoom;
            const gridInterval = zoom > 200 ? 0.1 : zoom > 50 ? 0.5 : 1;
            for (let t = Math.floor(startSec / gridInterval) * gridInterval; t < endSec; t += gridInterval) {
                const x = (t - scrollX) * zoom;
                ctx.beginPath();
                ctx.moveTo(x, 0);
                ctx.lineTo(x, height);
                ctx.stroke();
            }
        }

        // Draw each channel
        for (let ch = 0; ch < channels; ch++) {
            const data = buffer.getChannelData(ch);
            const yOffset = ch * channelHeight;
            const centerY = yOffset + channelHeight / 2;

            // Waveform
            ctx.fillStyle = waveColor06;

            const startSample = Math.floor(scrollX * buffer.sampleRate);
            const samplesPerPx = buffer.sampleRate / zoom;

            for (let px = 0; px < width; px++) {
                const sampleStart = Math.floor(startSample + px * samplesPerPx);
                const sampleEnd = Math.floor(startSample + (px + 1) * samplesPerPx);

                let min = 0;
                let max = 0;
                for (let s = sampleStart; s < sampleEnd && s < data.length; s++) {
                    if (s < 0) continue;
                    if (data[s] < min) min = data[s];
                    if (data[s] > max) max = data[s];
                }

                const top = centerY - max * (channelHeight * 0.45);
                const bottom = centerY - min * (channelHeight * 0.45);
                ctx.fillRect(px, top, 1, Math.max(1, bottom - top));
            }

            // RMS overlay (softer fill for perceived loudness)
            if (ds.editorShowRms) {
                ctx.fillStyle = waveColor03;
                for (let px = 0; px < width; px++) {
                    const sampleStart2 = Math.floor(startSample + px * samplesPerPx);
                    const sampleEnd2 = Math.floor(startSample + (px + 1) * samplesPerPx);

                    let sumSq = 0;
                    let count = 0;
                    for (let s = sampleStart2; s < sampleEnd2 && s < data.length; s++) {
                        if (s < 0) continue;
                        sumSq += data[s] * data[s];
                        count++;
                    }
                    const rms = count > 0 ? Math.sqrt(sumSq / count) : 0;
                    const rmsHeight = rms * channelHeight * 0.45;
                    ctx.fillRect(px, centerY - rmsHeight, 1, rmsHeight * 2);
                }
            }

            // Center line
            ctx.strokeStyle = "oklch(1 0 0 / 0.08)";
            ctx.beginPath();
            ctx.moveTo(0, centerY);
            ctx.lineTo(width, centerY);
            ctx.stroke();

            // Channel label
            ctx.fillStyle = "oklch(1 0 0 / 0.2)";
            ctx.font = "10px monospace";
            ctx.fillText(channels > 1 ? (ch === 0 ? "L" : "R") : "M", 4, yOffset + 14);
        }

        // Selection overlay
        if (selection) {
            const selLeft = (selection.start - scrollX) * zoom;
            const selWidth = (selection.end - selection.start) * zoom;
            ctx.fillStyle = waveColor015;
            ctx.fillRect(selLeft, 0, selWidth, height);
            ctx.strokeStyle = waveColor05;
            ctx.lineWidth = 1;
            ctx.strokeRect(selLeft, 0, selWidth, height);
        }

        // Markers
        for (const marker of editor.project.markers) {
            const mx = (marker.position - scrollX) * zoom;
            if (mx < 0 || mx > width) continue;
            ctx.strokeStyle = marker.color;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(mx, 0);
            ctx.lineTo(mx, height);
            ctx.stroke();
            // Label
            ctx.fillStyle = marker.color;
            ctx.font = "bold 9px sans-serif";
            ctx.fillText(marker.label, mx + 3, 12);
        }

        // Regions
        for (const region of editor.project.regions) {
            const rl = (region.start - scrollX) * zoom;
            const rw = (region.end - region.start) * zoom;
            ctx.fillStyle = region.color + "15";
            ctx.fillRect(rl, 0, rw, height);
            ctx.strokeStyle = region.color + "40";
            ctx.lineWidth = 1;
            ctx.strokeRect(rl, 0, rw, height);
            ctx.fillStyle = region.color;
            ctx.font = "bold 9px sans-serif";
            ctx.fillText(region.label, rl + 3, height - 6);
        }

        // Playhead
        const phx = (playPosition - scrollX) * zoom;
        if (phx >= 0 && phx <= width) {
            ctx.strokeStyle = "#22c55e";
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(phx, 0);
            ctx.lineTo(phx, height);
            ctx.stroke();
            // Triangle head
            ctx.fillStyle = "#22c55e";
            ctx.beginPath();
            ctx.moveTo(phx - 5, 0);
            ctx.lineTo(phx + 5, 0);
            ctx.lineTo(phx, 8);
            ctx.closePath();
            ctx.fill();
        }
    }, [editor.buffer, editor.scrollX, editor.zoom, editor.selection, editor.playPosition, editor.project.markers, editor.project.regions, dimensions, ds.editorWaveformColor, ds.editorShowRms, ds.editorShowGridLines]);

    // ΓöÇΓöÇΓöÇ Mouse interaction ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const pxToSeconds = useCallback((clientX: number): number => {
        const canvas = canvasRef.current;
        if (!canvas) return 0;
        const rect = canvas.getBoundingClientRect();
        const x = clientX - rect.left;
        return editor.scrollX + x / editor.zoom;
    }, [editor.scrollX, editor.zoom]);

    const handleMouseDown = useCallback((e: React.MouseEvent) => {
        if (e.button !== 0) return;
        const sec = pxToSeconds(e.clientX);

        if (editor.tool === "select") {
            setIsDragging(true);
            setDragStart(sec);
            editor.setSelection(null);
        } else if (editor.tool === "zoom") {
            if (e.altKey) {
                editor.setZoom(Math.max(10, editor.zoom * 0.7));
            } else {
                editor.setZoom(Math.min(5000, editor.zoom * 1.5));
                // Center on click
                editor.setScrollX(Math.max(0, sec - (dimensions.width / 2) / (editor.zoom * 1.5)));
            }
        } else if (editor.tool === "hand") {
            setIsDragging(true);
            setDragStart(e.clientX as unknown as number);
        }
    }, [editor, pxToSeconds, dimensions.width]);

    const handleMouseMove = useCallback((e: React.MouseEvent) => {
        if (!isDragging) return;
        const sec = pxToSeconds(e.clientX);

        if (editor.tool === "select" && dragStart !== null) {
            editor.setSelection({
                start: Math.min(dragStart, sec),
                end: Math.max(dragStart, sec),
            });
        } else if (editor.tool === "hand" && dragStart !== null) {
            const dx = e.clientX - dragStart;
            editor.setScrollX(Math.max(0, editor.scrollX - dx / editor.zoom));
            setDragStart(e.clientX);
        }
    }, [isDragging, dragStart, editor, pxToSeconds]);

    const handleMouseUp = useCallback(() => {
        setIsDragging(false);
        setDragStart(null);
    }, []);

    const handleClick = useCallback((e: React.MouseEvent) => {
        if (editor.tool === "select" && !editor.selection) {
            const sec = pxToSeconds(e.clientX);
            editor.seek(sec);
        }
    }, [editor, pxToSeconds]);

    // Wheel to zoom or scroll
    const handleWheel = useCallback((e: React.WheelEvent) => {
        if (e.ctrlKey) {
            e.preventDefault();
            const factor = e.deltaY > 0 ? 0.9 : 1.1;
            editor.setZoom(Math.max(10, Math.min(5000, editor.zoom * factor)));
        } else {
            const scrollDelta = e.deltaX !== 0 ? e.deltaX : e.deltaY;
            editor.setScrollX(Math.max(0, editor.scrollX + scrollDelta / editor.zoom));
        }
    }, [editor]);

    return (
        <div ref={containerRef} className="relative w-full h-full overflow-hidden bg-[oklch(0.14_0.01_260)]">
            <canvas
                ref={canvasRef}
                className="w-full h-full"
                style={{ cursor: editor.tool === "hand" ? "grab" : editor.tool === "zoom" ? "zoom-in" : "text" }}
                onMouseDown={handleMouseDown}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
                onClick={handleClick}
                onWheel={handleWheel}
            />
        </div>
    );
}

"use client";

import { createContext, useContext, useState, useRef, useCallback, useEffect, type ReactNode } from "react";
import { usePlayer } from "./player-context";
import {
    EQEngine,
    DEFAULT_BANDS,
    DEFAULT_EFFECTS,
    EQ_PRESETS,
    type EQBand,
    type EffectState,
} from "@/lib/eq-engine";

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface EQState {
    enabled: boolean;
    bands: EQBand[];
    preGain: number;         // dB, -12 to +12
    effects: EffectState;
    activePreset: string | null;
    mode: "easy" | "advanced";
}

interface EQActions {
    toggle: () => void;
    setBandGain: (index: number, gain: number) => void;
    setBandQ: (index: number, Q: number) => void;
    setPreGain: (gain: number) => void;
    applyPreset: (name: string) => void;
    resetAll: () => void;
    setEffect: <K extends keyof EffectState>(key: K, value: EffectState[K]) => void;
    setEffects: (partial: Partial<EffectState>) => void;
    setMode: (mode: "easy" | "advanced") => void;
    // Easy mode helpers (3-band)
    setEasyBass: (gain: number) => void;
    setEasyMid: (gain: number) => void;
    setEasyTreble: (gain: number) => void;
    getEasyBass: () => number;
    getEasyMid: () => number;
    getEasyTreble: () => number;
    // Engine access
    getCompressorReduction: () => number;
    connectEngine: (ctx: AudioContext, source: MediaElementAudioSourceNode, analyser: AnalyserNode) => void;
}

type EQContextType = EQState & EQActions;

// ΓöÇΓöÇΓöÇ Storage ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const STORAGE_KEY = "music-organizer-eq";

function loadEQState(): Partial<EQState> {
    if (typeof window === "undefined") return {};
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) return {};
        return JSON.parse(raw);
    } catch {
        return {};
    }
}

function saveEQState(state: EQState) {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify({
            enabled: state.enabled,
            bands: state.bands,
            preGain: state.preGain,
            effects: state.effects,
            activePreset: state.activePreset,
            mode: state.mode,
        }));
    } catch { /* storage full */ }
}

// ΓöÇΓöÇΓöÇ Context ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const EQContext = createContext<EQContextType | null>(null);

export function useEQ() {
    const ctx = useContext(EQContext);
    if (!ctx) throw new Error("useEQ must be used within EQProvider");
    return ctx;
}

// ΓöÇΓöÇΓöÇ Provider ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export function EQProvider({ children }: { children: ReactNode }) {
    const engineRef = useRef<EQEngine | null>(null);
    const connectedRef = useRef(false);

    const [state, setState] = useState<EQState>(() => {
        const saved = loadEQState();
        return {
            enabled: saved.enabled ?? false,
            bands: saved.bands ?? DEFAULT_BANDS.map(b => ({ ...b })),
            preGain: saved.preGain ?? 0,
            effects: saved.effects ?? { ...DEFAULT_EFFECTS },
            activePreset: saved.activePreset ?? null,
            mode: saved.mode ?? "easy",
        };
    });

    // Persist on change
    useEffect(() => {
        saveEQState(state);
    }, [state]);

    // Sync engine when state changes
    useEffect(() => {
        const engine = engineRef.current;
        if (!engine) return;

        if (state.enabled) {
            engine.setPreGain(Math.pow(10, state.preGain / 20));
            state.bands.forEach((b, i) => {
                engine.setBandGain(i, b.gain);
                engine.setBandQ(i, b.Q);
            });
        } else {
            // Bypass: flat gains
            engine.setPreGain(1);
            state.bands.forEach((_, i) => engine.setBandGain(i, 0));
        }
    }, [state.enabled, state.bands, state.preGain]);

    // Sync effects
    useEffect(() => {
        const engine = engineRef.current;
        if (!engine) return;
        const e = state.effects;
        const active = state.enabled;
        engine.updateCompressor(
            active && e.compressorEnabled, e.compressorThreshold, e.compressorKnee,
            e.compressorRatio, e.compressorAttack, e.compressorRelease
        );
        engine.updateReverb(active && e.reverbEnabled, e.reverbMix, e.reverbDecay);
        engine.updateDelay(active && e.delayEnabled, e.delayTime, e.delayFeedback, e.delayMix);
        engine.updateBassBoost(active && e.bassBoostEnabled, e.bassBoostAmount);
    }, [state.enabled, state.effects]);

    // Connect the engine to an existing AudioContext
    const connectEngine = useCallback((ctx: AudioContext, source: MediaElementAudioSourceNode, analyser: AnalyserNode) => {
        if (connectedRef.current) return;

        const engine = new EQEngine(ctx);
        engineRef.current = engine;

        // Disconnect source ΓåÆ analyser, re-route through engine
        source.disconnect();
        source.connect(engine.input);
        engine.output.connect(analyser);
        // analyser ΓåÆ destination is already connected

        connectedRef.current = true;
    }, []);

    // Auto-connect to player's audio nodes
    const player = usePlayer();
    useEffect(() => {
        if (connectedRef.current) return;
        const nodes = player.getAudioNodes();
        if (!nodes) return;
        connectEngine(nodes.ctx, nodes.source, nodes.analyser);
    });

    const toggle = useCallback(() => {
        setState(s => ({ ...s, enabled: !s.enabled }));
    }, []);

    const setBandGain = useCallback((index: number, gain: number) => {
        setState(s => {
            const bands = s.bands.map((b, i) => i === index ? { ...b, gain } : b);
            return { ...s, bands, activePreset: null };
        });
    }, []);

    const setBandQ = useCallback((index: number, Q: number) => {
        setState(s => {
            const bands = s.bands.map((b, i) => i === index ? { ...b, Q } : b);
            return { ...s, bands };
        });
    }, []);

    const setPreGain = useCallback((preGain: number) => {
        setState(s => ({ ...s, preGain }));
    }, []);

    const applyPreset = useCallback((name: string) => {
        const preset = EQ_PRESETS.find(p => p.name === name);
        if (!preset) return;
        setState(s => ({
            ...s,
            bands: s.bands.map((b, i) => ({ ...b, gain: preset.bands[i] ?? 0 })),
            activePreset: name,
            enabled: true,
        }));
    }, []);

    const resetAll = useCallback(() => {
        setState(s => ({
            ...s,
            bands: DEFAULT_BANDS.map(b => ({ ...b })),
            preGain: 0,
            effects: { ...DEFAULT_EFFECTS },
            activePreset: "Flat",
        }));
    }, []);

    const setEffect = useCallback(<K extends keyof EffectState>(key: K, value: EffectState[K]) => {
        setState(s => ({
            ...s,
            effects: { ...s.effects, [key]: value },
        }));
    }, []);

    const setEffects = useCallback((partial: Partial<EffectState>) => {
        setState(s => ({
            ...s,
            effects: { ...s.effects, ...partial },
        }));
    }, []);

    const setMode = useCallback((mode: "easy" | "advanced") => {
        setState(s => ({ ...s, mode }));
    }, []);

    // Easy mode: map 3 bands (bass=avg of 0-2, mid=avg of 3-6, treble=avg of 7-9)
    const getEasyBass = useCallback(() => {
        const { bands } = state;
        return (bands[0].gain + bands[1].gain + bands[2].gain) / 3;
    }, [state.bands]);

    const getEasyMid = useCallback(() => {
        const { bands } = state;
        return (bands[3].gain + bands[4].gain + bands[5].gain + bands[6].gain) / 4;
    }, [state.bands]);

    const getEasyTreble = useCallback(() => {
        const { bands } = state;
        return (bands[7].gain + bands[8].gain + bands[9].gain) / 3;
    }, [state.bands]);

    const setEasyBass = useCallback((gain: number) => {
        setState(s => ({
            ...s,
            bands: s.bands.map((b, i) =>
                i <= 2 ? { ...b, gain: Math.round(gain * 10) / 10 } : b
            ),
            activePreset: null,
        }));
    }, []);

    const setEasyMid = useCallback((gain: number) => {
        setState(s => ({
            ...s,
            bands: s.bands.map((b, i) =>
                i >= 3 && i <= 6 ? { ...b, gain: Math.round(gain * 10) / 10 } : b
            ),
            activePreset: null,
        }));
    }, []);

    const setEasyTreble = useCallback((gain: number) => {
        setState(s => ({
            ...s,
            bands: s.bands.map((b, i) =>
                i >= 7 ? { ...b, gain: Math.round(gain * 10) / 10 } : b
            ),
            activePreset: null,
        }));
    }, []);

    const getCompressorReduction = useCallback(() => {
        return engineRef.current?.getCompressorReduction() ?? 0;
    }, []);

    return (
        <EQContext.Provider value={{
            ...state,
            toggle,
            setBandGain,
            setBandQ,
            setPreGain,
            applyPreset,
            resetAll,
            setEffect,
            setEffects,
            setMode,
            setEasyBass,
            setEasyMid,
            setEasyTreble,
            getEasyBass,
            getEasyMid,
            getEasyTreble,
            getCompressorReduction,
            connectEngine,
        }}>
            {children}
        </EQContext.Provider>
    );
}

