                                            "text-[11px] font-medium truncate",
                                            isHidden ? "text-white/45" : "text-white/85",
                                        )}>{w.title}</span>
                                        {/* Status pill */}
                                        {isHidden && (
                                            <span className="text-[7.5px] uppercase tracking-wider px-1 py-px rounded bg-white/[0.04] text-white/35">Hidden</span>
