                                        )}
                                    </div>
                                    <div className="text-[8.5px] text-white/30 tabular-nums truncate">
                                        {w.description ?? (
                                            layout
                                                ? `${layout.w}├ù${layout.h} ┬╖ (${layout.x},${layout.y})`
