}: MixerBrowserModalProps) {
    useRenderCount("MixerBrowserModal");
    const mixer = useMixerActions();
    const { noteNotations } = useDAWSettings();

    // ΓöÇΓöÇ Local library state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [tracks, setTracks] = useState<Track[]>([]);
    const [total, setTotal] = useState(0);
    const [search, setSearch] = useState("");
    const [selectedIndex, setSelectedIndex] = useState(0);
    const [loading, setLoading] = useState(false);
    const [localCollapsed, setLocalCollapsed] = useState(false);
    const [localVisibleCount, setLocalVisibleCount] = useState(INITIAL_VISIBLE);
    const listRef = useRef<HTMLDivElement>(null);
    const searchRef = useRef<HTMLInputElement>(null);

    // ΓöÇΓöÇ Provider state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [enabledProviders, setEnabledProviders] = useState<Set<string>>(new Set());
    const [providerStates, setProviderStates] = useState<Record<string, ProviderState>>({});
    // Mirror of `providerStates` kept in a ref so callbacks (esp. the
    // debounced search effect) can read the latest value without re-creating
    // their identity on every state update. Without this, `searchProviders`
    // changes on every successful search ΓåÆ its dependent useEffect fires
    // again ΓåÆ another search ΓåÆ infinite refresh loop while typing stays idle.
    const providerStatesRef = useRef(providerStates);
    useEffect(() => { providerStatesRef.current = providerStates; }, [providerStates]);
    const [showProviderPicker, setShowProviderPicker] = useState(false);

    // ΓöÇΓöÇ Download modal state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [downloadTrack, setDownloadTrack] = useState<TrackDownloadInfo | null>(null);
    const [downloadModalOpen, setDownloadModalOpen] = useState(false);

    // ΓöÇΓöÇ Duplicate detection state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const [dupeResults, setDupeResults] = useState<Record<string, SearchDupeResult>>({});

    // ΓöÇΓöÇ Fetch local library tracks ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const fetchTracks = useCallback(async (query: string) => {
        setLoading(true);
        try {
            const result = await getTracks({
                search: query || undefined,
                pageSize: 200,
                sort: "title",
                order: "asc",
            });
            setTracks(result.tracks);
            setTotal(result.total);
            setSelectedIndex(0);
            setLocalVisibleCount(INITIAL_VISIBLE);
        } finally {
            setLoading(false);
        }
    }, []);

    // ΓöÇΓöÇ Fetch from external providers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const searchProviders = useCallback(async (query: string, providers: Set<string>, searchTypeOverride?: SearchType) => {
        if (!query.trim() || providers.size === 0) return;

        const activeProviders = Array.from(providers);
        const currentStates = providerStatesRef.current;

        // Group providers by their search mode (or use override for all)
        const providersByMode = new Map<SearchType, string[]>();
        for (const p of activeProviders) {
            const mode = searchTypeOverride || (currentStates[p]?.searchMode ?? "tracks");
            const list = providersByMode.get(mode) || [];
            list.push(p);
            providersByMode.set(mode, list);
        }

        // Set loading state
        setProviderStates(prev => {
            const next = { ...prev };
            for (const p of activeProviders) {
                const mode = searchTypeOverride || (prev[p]?.searchMode ?? "tracks");
                next[p] = {
                    ...next[p],
                    loading: true,
                    error: undefined,
                    trackResults: next[p]?.trackResults || [],
                    playlistResults: next[p]?.playlistResults || [],
                    collapsed: next[p]?.collapsed ?? false,
                    visibleCount: next[p]?.visibleCount ?? INITIAL_VISIBLE,
                    searchMode: mode,
                };
            }
            return next;
        });

        // Search each mode group
        for (const [searchType, modeProviders] of providersByMode) {
            try {
                const res = await fetch("/api/download/search", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        query: query.trim(),
                        providers: modeProviders,
                        limit: 15,
                        searchType,
                    }),
                });

                if (!res.ok) {
                    const err = await res.json().catch(() => ({}));
                    throw new Error(err.error || `Search failed: ${res.status}`);
                }

                const data = await res.json();
                const results: ProviderSearchResult[] = data.results || [];

                setProviderStates(prev => {
                    const next = { ...prev };
                    for (const r of results) {
                        const isPlaylist = searchType === "playlists";
                        next[r.provider] = {
                            ...next[r.provider],
                            trackResults: isPlaylist ? (prev[r.provider]?.trackResults || []) : r.results,
                            playlistResults: isPlaylist ? r.results : (prev[r.provider]?.playlistResults || []),
                            loading: false,
                            error: r.error,
                            collapsed: prev[r.provider]?.collapsed ?? false,
                            visibleCount: INITIAL_VISIBLE,
                            searchMode: prev[r.provider]?.searchMode ?? "tracks",
                        };
                    }
                    // Clear loading for providers that didn't return results
                    for (const p of modeProviders) {
                        if (!results.find(r => r.provider === p)) {
                            next[p] = { ...next[p], loading: false };
                        }
                    }
                    return next;
                });

                // Check duplicates for track results
                if (searchType === "tracks") {
                    const allTrackResults = results.flatMap(r => r.results.filter(s => !s.isPlaylist));
                    if (allTrackResults.length > 0) {
                        checkDuplicates(allTrackResults);
                    }
                }
            } catch (err) {
                const message = err instanceof Error ? err.message : "Search failed";
                setProviderStates(prev => {
                    const next = { ...prev };
                    for (const p of modeProviders) {
                        next[p] = { ...next[p], loading: false, error: message };
                    }
                    return next;
                });
            }
        }
        // No state deps ΓÇö we read latest via providerStatesRef so the debounced
        // search effect doesn't loop. setProviderStates updaters use `prev`.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // ΓöÇΓöÇ Check duplicates against library ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const checkDuplicates = useCallback(async (results: SearchResult[]) => {
        try {
            const items = results.map(r => ({
                id: r.id,
                title: r.title,
                uploader: r.uploader,
            }));
            const res = await fetch("/api/download/search-duplicates", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ items }),
            });
            if (!res.ok) return;
            const data = await res.json();
            if (data.results) {
                setDupeResults(prev => ({ ...prev, ...data.results }));
            }
        } catch {
            // Non-critical, silently fail
        }
    }, []);

    // ΓöÇΓöÇ Open handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    useEffect(() => {
        if (open) {
            fetchTracks(search);
            setTimeout(() => searchRef.current?.focus(), 100);
        }
    }, [open]);

    // ΓöÇΓöÇ Debounced search ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const searchTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
    const providerSearchTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);

    useEffect(() => {
        if (!open) return;
        if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
        searchTimerRef.current = setTimeout(() => fetchTracks(search), 300);
        return () => { if (searchTimerRef.current) clearTimeout(searchTimerRef.current); };
    }, [search, open, fetchTracks]);

    // Provider search ΓÇö longer debounce (600ms) since it's external
    useEffect(() => {
        if (!open || enabledProviders.size === 0 || !search.trim()) return;
        if (providerSearchTimerRef.current) clearTimeout(providerSearchTimerRef.current);
        providerSearchTimerRef.current = setTimeout(() => searchProviders(search, enabledProviders), 600);
        return () => { if (providerSearchTimerRef.current) clearTimeout(providerSearchTimerRef.current); };
    }, [search, open, enabledProviders, searchProviders]);

    // ΓöÇΓöÇ Keyboard navigation (local tracks only) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const navigate = useCallback((direction: number) => {
        setSelectedIndex(prev => {
            const visibleTracks = localCollapsed ? 0 : Math.min(tracks.length, localVisibleCount);
            const next = Math.max(0, Math.min(visibleTracks - 1, prev + direction));
            const el = listRef.current?.querySelector(`[data-local-idx="${next}"]`) as HTMLElement;
            el?.scrollIntoView({ block: "nearest" });
            return next;
        });
    }, [tracks.length, localCollapsed, localVisibleCount]);

    const loadSelected = useCallback(() => {
        const visibleTracks = tracks.slice(0, localVisibleCount);
        const track = visibleTracks[selectedIndex];
        if (track) {
            mixer.loadTrack(targetDeck, track);
            onOpenChange(false);
        }
    }, [tracks, selectedIndex, localVisibleCount, targetDeck, mixer, onOpenChange]);

    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === "ArrowDown") { e.preventDefault(); navigate(1); }
        else if (e.key === "ArrowUp") { e.preventDefault(); navigate(-1); }
        else if (e.key === "Enter") { e.preventDefault(); loadSelected(); }
        else if (e.key === "Tab") { e.preventDefault(); onDeckChange(targetDeck === "A" ? "B" : "A"); }
    }, [navigate, loadSelected, targetDeck, onDeckChange]);

    // ΓöÇΓöÇ MIDI handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    useEffect(() => {
        if (!open) return;
        const handler = (e: CustomEvent) => {
            if (e.detail.action === "navigate") navigate(e.detail.direction);
            else if (e.detail.action === "load") loadSelected();
        };
        window.addEventListener("mixer-browser-action" as string, handler as EventListener);
        return () => window.removeEventListener("mixer-browser-action" as string, handler as EventListener);
    }, [open, navigate, loadSelected]);

    // ΓöÇΓöÇ Toggle provider ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const toggleProvider = useCallback((id: string) => {
        setEnabledProviders(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    }, []);

    // ΓöÇΓöÇ Download handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const handleDownload = useCallback((result: SearchResult) => {
        // Playlist: open download page in new tab
        if (result.isPlaylist) {
            const url = `/download?url=${encodeURIComponent(result.url)}&auto=1`;
            window.open(url, "_blank", "noopener");
            return;
        }

        setDownloadTrack({
            url: result.url,
            downloadUrl: result.downloadUrl,
            title: result.title,
            artist: result.uploader,
            duration: result.duration,
            thumbnail: result.thumbnail,
            extractor: result.extractor,
        });
        setDownloadModalOpen(true);
    }, []);

    const handleLoadToDeck = useCallback(async (trackId: number, deck: DeckSide) => {
        const track = await getTrackById(trackId);
        if (track) {
            mixer.loadTrack(deck, track);
            // Refresh local library list so the just-loaded track shows up if
            // the user re-opens the picker.
            void fetchTracks(search);
            onOpenChange(false);
        } else {
            console.warn("[mixer-browser] handleLoadToDeck: track not found in DB", trackId);
        }
    }, [mixer, onOpenChange, fetchTracks, search]);

    // ΓöÇΓöÇ Provider section collapse toggle ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const toggleProviderCollapse = useCallback((id: string) => {
        setProviderStates(prev => ({
            ...prev,
            [id]: { ...prev[id], collapsed: !prev[id]?.collapsed },
        }));
    }, []);

    const loadMoreProvider = useCallback((id: string) => {
        setProviderStates(prev => ({
            ...prev,
            [id]: { ...prev[id], visibleCount: (prev[id]?.visibleCount || INITIAL_VISIBLE) + LOAD_MORE_COUNT },
        }));
    }, []);

    // ΓöÇΓöÇ Switch search mode (tracks/playlists) for a provider ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const toggleSearchMode = useCallback((providerId: string, mode: SearchType) => {
        setProviderStates(prev => ({
            ...prev,
            [providerId]: {
                ...prev[providerId],
                searchMode: mode,
                visibleCount: INITIAL_VISIBLE,
                trackResults: prev[providerId]?.trackResults || [],
                playlistResults: prev[providerId]?.playlistResults || [],
                loading: prev[providerId]?.loading ?? false,
                collapsed: prev[providerId]?.collapsed ?? false,
            },
        }));

        // If we don't have results for this mode yet, fetch them
        const state = providerStatesRef.current[providerId];
        const hasResults = mode === "playlists"
            ? (state?.playlistResults?.length ?? 0) > 0
            : (state?.trackResults?.length ?? 0) > 0;

        if (!hasResults && search.trim()) {
            searchProviders(search, new Set([providerId]), mode);
        }
    }, [search, searchProviders]);

    // ΓöÇΓöÇ Helper: count visible local tracks ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const visibleLocalTracks = localCollapsed ? [] : tracks.slice(0, localVisibleCount);

    return (
        <>
            <Dialog open={open} onOpenChange={onOpenChange}>
                <DialogContent
                    className="sm:max-w-[600px] max-h-[85vh] p-0 overflow-hidden bg-zinc-950 border-white/10 z-[80]"
                    overlayClassName="z-[79]"
                    onKeyDown={handleKeyDown}
                >
                    {/* Header */}
                    <div className="p-3 pb-2 border-b border-white/[0.06]">
                        <DialogTitle className="flex items-center justify-between text-sm font-semibold text-white/90 mb-2">
                            <div className="flex items-center gap-2">
                                <Disc3 className="h-4 w-4" />
                                Load Track
                            </div>
                            <div className="flex gap-1">
                                {(["A", "B", "C", "D"] as DeckSide[]).map(side => (
                                    <button
                                        key={side}
                                        onClick={() => onDeckChange(side)}
                                        className={cn(
                                            "px-2 py-1 rounded text-[10px] font-bold transition-colors cursor-pointer",
                                            targetDeck === side
                                                ? side === "A" || side === "C" ? "bg-purple-500/30 text-purple-300" : "bg-blue-500/30 text-blue-300"
                                                : "bg-white/5 text-white/30 hover:text-white/60"
                                        )}
                                    >
                                        {side}
                                    </button>
                                ))}
                            </div>
                        </DialogTitle>

                        {/* Search input */}
                        <div className="relative">
                            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-white/30" />
                            <input
                                ref={searchRef}
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                placeholder="Search local library & streaming providers..."
                                className="w-full pl-8 pr-3 py-2 rounded-md bg-white/5 border border-white/[0.08] text-xs text-white/90 placeholder-white/25 outline-none focus:border-white/20"
                            />
                        </div>

                        {/* Provider toggles */}
                        <div className="flex items-center gap-1.5 mt-2 flex-wrap">
                            <button
                                onClick={() => setShowProviderPicker(p => !p)}
                                className="flex items-center gap-1 px-2 py-1 rounded text-[10px] bg-white/5 text-white/40 hover:text-white/60 hover:bg-white/10 transition-colors cursor-pointer border border-white/[0.06]"
                            >
                                <Globe className="h-3 w-3" />
                                Providers
                                <ChevronDown className={cn("h-2.5 w-2.5 transition-transform", showProviderPicker && "rotate-180")} />
                            </button>
                            {enabledProviders.size > 0 && (
                                <span className="text-[9px] text-white/25">
                                    {enabledProviders.size} active
                                </span>
                            )}
                            {/* Quick-toggle chips for enabled providers */}
                            {PROVIDERS.filter(p => enabledProviders.has(p.id)).map(p => (
                                <span key={p.id} className={cn("px-1.5 py-0.5 rounded text-[9px] font-medium", p.bgColor, p.color)}>
                                    {p.icon} {p.label}
                                </span>
                            ))}
                        </div>

                        {/* Provider picker dropdown */}
                        {showProviderPicker && (
                            <div className="mt-2 rounded-lg bg-white/[0.03] border border-white/[0.06] p-2 space-y-1">
                                <div className="flex items-center justify-between mb-1">
                                    <div className="text-[9px] uppercase tracking-wider text-white/20">Streaming Providers</div>
                                    <div className="flex items-center gap-1.5">
                                        <button
                                            onClick={() => setEnabledProviders(new Set(PROVIDERS.map(p => p.id)))}
                                            className="text-[9px] text-purple-400/60 hover:text-purple-400 cursor-pointer transition-colors"
                                        >
                                            All
                                        </button>
                                        <span className="text-[9px] text-white/10">┬╖</span>
                                        <button
                                            onClick={() => setEnabledProviders(new Set())}
                                            className="text-[9px] text-white/30 hover:text-white/60 cursor-pointer transition-colors"
                                        >
                                            None
                                        </button>
                                    </div>
                                </div>
                                {PROVIDERS.map(p => (
                                    <label
                                        key={p.id}
                                        className="flex items-center gap-2 py-1 px-1.5 rounded hover:bg-white/[0.04] cursor-pointer transition-colors"
                                    >
                                        <div className="relative">
                                            <input
                                                type="checkbox"
                                                checked={enabledProviders.has(p.id)}
                                                onChange={() => toggleProvider(p.id)}
                                                className="sr-only peer"
                                            />
                                            <div className={cn(
                                                "w-3.5 h-3.5 rounded border border-white/20 bg-white/5 flex items-center justify-center transition-colors",
                                                enabledProviders.has(p.id) && "bg-purple-500/30 border-purple-500/50"
                                            )}>
                                                {enabledProviders.has(p.id) && (
                                                    <svg className="w-2.5 h-2.5 text-purple-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                                                        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                                                    </svg>
                                                )}
                                            </div>
                                        </div>
                                        <span className={cn("text-[11px]", enabledProviders.has(p.id) ? p.color : "text-white/40")}>
                                            {p.icon} {p.label}
                                        </span>
                                    </label>
                                ))}
                                <p className="text-[8px] text-white/15 mt-1 px-1">
                                    Search results from external providers require downloading before loading to a deck
                                </p>
                            </div>
                        )}

                        <div className="flex items-center justify-between mt-2">
                            <span className="text-[10px] text-white/30">{total} tracks in library</span>
                            <div className="flex items-center gap-2 text-[9px] text-white/20">
                                <span className="flex items-center gap-0.5"><ChevronUp className="h-2.5 w-2.5" /><ChevronDown className="h-2.5 w-2.5" /> Navigate</span>
                                <span>Γå╡ Load</span>
                                <span>Tab Deck</span>
                            </div>
                        </div>
                    </div>

                    {/* Results area */}
                    <div ref={listRef} className="overflow-y-auto max-h-[55vh]">
                        {/* ΓöÇΓöÇ Local Library Section ΓöÇΓöÇ */}
                        <div>
                            <button
                                onClick={() => setLocalCollapsed(c => !c)}
                                className="w-full flex items-center justify-between px-3 py-1.5 bg-white/[0.02] border-b border-white/[0.04] cursor-pointer hover:bg-white/[0.04] transition-colors"
                            >
                                <div className="flex items-center gap-2">
                                    <Library className="h-3 w-3 text-purple-400/60" />
                                    <span className="text-[10px] font-semibold text-white/60 uppercase tracking-wider">Library</span>
                                    <span className="text-[9px] text-white/25">{total} tracks</span>
                                </div>
                                <ChevronRight className={cn("h-3 w-3 text-white/20 transition-transform", !localCollapsed && "rotate-90")} />
                            </button>

                            {!localCollapsed && (
                                <>
                                    {loading && tracks.length === 0 ? (
                                        <div className="flex items-center justify-center py-8 text-white/20 text-xs">
                                            <Loader2 className="h-4 w-4 animate-spin mr-2" /> Loading...
                                        </div>
                                    ) : visibleLocalTracks.length === 0 && search ? (
                                        <div className="flex items-center justify-center py-6 text-white/15 text-[10px] gap-1">
                                            <Search className="h-3 w-3" /> No local matches
                                        </div>
                                    ) : (
                                        <>
                                            {visibleLocalTracks.map((track, i) => (
                                                <button
                                                    key={track.id}
                                                    data-local-idx={i}
                                                    onClick={() => {
                                                        setSelectedIndex(i);
                                                        mixer.loadTrack(targetDeck, track);
                                                        onOpenChange(false);
                                                    }}
                                                    onMouseEnter={() => setSelectedIndex(i)}
                                                    className={cn(
                                                        "w-full flex items-center gap-3 px-3 py-2 text-left transition-colors cursor-pointer",
                                                        i === selectedIndex ? "bg-white/10" : "hover:bg-white/[0.04]",
                                                        i !== visibleLocalTracks.length - 1 && "border-b border-white/[0.03]"
                                                    )}
                                                >
                                                    <div className="h-9 w-9 rounded overflow-hidden bg-white/5 shrink-0">
                                                        {track.artworkUrl ? (
                                                            <img src={track.artworkUrl} alt="" className="h-full w-full object-cover" />
                                                        ) : (
                                                            <div className="h-full w-full flex items-center justify-center">
                                                                <Disc3 className="h-4 w-4 text-white/15" />
                                                            </div>
                                                        )}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <div className="text-xs text-white/80 truncate">{track.title || track.filename}</div>
                                                        <div className="text-[10px] text-white/35 truncate">{track.artist || "Unknown"}</div>
                                                    </div>
                                                    <div className="flex items-center gap-1.5 shrink-0">
                                                        {track.bpm && (
                                                            <span className="text-[9px] px-1 py-0.5 rounded bg-white/5 text-white/30 tabular-nums">
                                                                {Math.round(track.bpm)}
                                                            </span>
                                                        )}
                                                        {track.keyCamelot && (
                                                            <span className="text-[9px] px-1 py-0.5 rounded bg-white/5 text-white/30">
                                                                {formatKey(track.keyCamelot, noteNotations)}
                                                            </span>
                                                        )}
                                                        {track.genre && (
                                                            <span className="text-[9px] px-1 py-0.5 rounded bg-purple-500/10 text-purple-300/60 truncate max-w-[60px]">
                                                                {track.genre}
                                                            </span>
                                                        )}
                                                    </div>
                                                </button>
                                            ))}
                                            {tracks.length > localVisibleCount && (
                                                <button
                                                    onClick={() => setLocalVisibleCount(c => c + LOAD_MORE_COUNT)}
                                                    className="w-full py-2 text-[10px] text-purple-400/60 hover:text-purple-400 hover:bg-white/[0.03] transition-colors cursor-pointer"
                                                >
                                                    Show more ({tracks.length - localVisibleCount} remaining)
                                                </button>
                                            )}
                                        </>
                                    )}
                                </>
                            )}
                        </div>

                        {/* ΓöÇΓöÇ Provider Sections ΓöÇΓöÇ */}
                        {PROVIDERS.filter(p => enabledProviders.has(p.id)).map(provider => {
                            const state = providerStates[provider.id];
                            const searchMode = state?.searchMode ?? "tracks";
                            const results = searchMode === "playlists"
                                ? (state?.playlistResults || [])
                                : (state?.trackResults || []);
                            const isCollapsed = state?.collapsed ?? false;
                            const visibleCount = state?.visibleCount || INITIAL_VISIBLE;
                            const visibleResults = results.slice(0, visibleCount);
                            const isLoading = state?.loading ?? false;
                            const canSearchPlaylists = PLAYLIST_CAPABLE_PROVIDERS.has(provider.id);

                            return (
                                <div key={provider.id}>
                                    {/* Provider header */}
                                    <div className="flex items-center justify-between px-3 py-1.5 bg-white/[0.02] border-y border-white/[0.04]">
                                        <button
                                            onClick={() => toggleProviderCollapse(provider.id)}
                                            className="flex items-center gap-2 cursor-pointer hover:opacity-80 transition-opacity"
                                        >
                                            <span className={cn("text-xs", provider.color)}>{provider.icon}</span>
                                            <span className="text-[10px] font-semibold text-white/60 uppercase tracking-wider">{provider.label}</span>
                                            {isLoading ? (
                                                <Loader2 className="h-3 w-3 animate-spin text-white/20" />
                                            ) : (
                                                <span className="text-[9px] text-white/25">{results.length} results</span>
                                            )}
                                            <ChevronRight className={cn("h-3 w-3 text-white/20 transition-transform", !isCollapsed && "rotate-90")} />
                                        </button>

                                        {/* Songs / Playlists toggle */}
                                        {canSearchPlaylists && (
                                            <div className="flex items-center bg-white/[0.04] rounded-md overflow-hidden border border-white/[0.06]">
                                                <button
                                                    onClick={() => toggleSearchMode(provider.id, "tracks")}
                                                    className={cn(
                                                        "flex items-center gap-1 px-2 py-0.5 text-[9px] transition-colors cursor-pointer",
                                                        searchMode === "tracks"
                                                            ? "bg-purple-500/20 text-purple-300"
                                                            : "text-white/30 hover:text-white/50"
                                                    )}
                                                >
                                                    <Music className="h-2.5 w-2.5" />
                                                    Songs
                                                </button>
                                                <button
                                                    onClick={() => toggleSearchMode(provider.id, "playlists")}
                                                    className={cn(
                                                        "flex items-center gap-1 px-2 py-0.5 text-[9px] transition-colors cursor-pointer",
                                                        searchMode === "playlists"
                                                            ? "bg-purple-500/20 text-purple-300"
                                                            : "text-white/30 hover:text-white/50"
                                                    )}
                                                >
                                                    <ListMusic className="h-2.5 w-2.5" />
                                                    Playlists
                                                </button>
                                            </div>
                                        )}
                                    </div>

                                    {!isCollapsed && (
                                        <>
                                            {isLoading && results.length === 0 ? (
                                                <div className="flex items-center justify-center py-6 text-white/20 text-[10px]">
                                                    <Loader2 className="h-3.5 w-3.5 animate-spin mr-2" />
                                                    Searching {provider.label}...
                                                </div>
                                            ) : state?.error ? (
                                                <div className="px-3 py-4 text-[10px] text-red-400/60 text-center">
                                                    {state.error}
                                                </div>
                                            ) : results.length === 0 && search.trim() ? (
                                                <div className="px-3 py-4 text-[10px] text-white/15 text-center">
                                                    No {searchMode === "playlists" ? "playlists" : "results"} from {provider.label}
                                                </div>
                                            ) : (
                                                <>
                                                    {visibleResults.map((result) => {
                                                        const dupe = dupeResults[result.id];
                                                        const isInLibrary = !!dupe?.inLibrary;
                                                        const isVariant = !!dupe?.isVariantOf && !isInLibrary;

                                                        return (
                                                            <div
                                                                key={`${provider.id}-${result.id}`}
                                                                className={cn(
                                                                    "flex items-center gap-3 px-3 py-2 border-b border-white/[0.03] hover:bg-white/[0.04] transition-colors group",
                                                                    isInLibrary && "opacity-50"
                                                                )}
                                                            >
                                                                {/* Thumbnail */}
                                                                <div className="h-9 w-9 rounded overflow-hidden bg-white/5 shrink-0 relative">
                                                                    {result.thumbnail ? (
                                                                        <img src={result.thumbnail} alt="" className="h-full w-full object-cover" />
                                                                    ) : (
                                                                        <div className="h-full w-full flex items-center justify-center">
                                                                            {result.isPlaylist ? (
                                                                                <ListMusic className="h-4 w-4 text-white/15" />
                                                                            ) : (
                                                                                <Music className="h-4 w-4 text-white/15" />
                                                                            )}
                                                                        </div>
                                                                    )}
                                                                    {/* Playlist track count badge */}
                                                                    {result.isPlaylist && result.trackCount != null && (
                                                                        <div className="absolute bottom-0 right-0 bg-black/70 rounded-tl px-1 text-[7px] text-white/60">
                                                                            {result.trackCount}
                                                                        </div>
                                                                    )}
                                                                </div>

                                                                {/* Info */}
                                                                <div className="flex-1 min-w-0">
                                                                    <div className="flex items-center gap-1.5">
                                                                        <span className="text-xs text-white/80 truncate">{result.title}</span>
                                                                        {/* In Library badge */}
                                                                        {isInLibrary && (
                                                                            <span className="flex items-center gap-0.5 shrink-0 px-1 py-0.5 rounded text-[8px] font-medium bg-green-500/15 text-green-400/80 border border-green-500/20">
                                                                                <Check className="h-2 w-2" />
                                                                                In Library
                                                                            </span>
                                                                        )}
                                                                        {/* Variant badge */}
                                                                        {isVariant && (
                                                                            <span className="flex items-center gap-0.5 shrink-0 px-1 py-0.5 rounded text-[8px] font-medium bg-blue-500/15 text-blue-400/80 border border-blue-500/20"
                                                                                title={`Variant of: ${dupe.isVariantOf!.title}`}
                                                                            >
                                                                                <GitBranch className="h-2 w-2" />
                                                                                Variant
                                                                            </span>
                                                                        )}
                                                                    </div>
                                                                    <div className="text-[10px] text-white/35 truncate">
                                                                        {result.uploader}
                                                                        {result.album && <span className="text-white/20"> ┬╖ {result.album}</span>}
                                                                        {result.isPlaylist && result.trackCount != null && (
                                                                            <span className="text-white/20"> ┬╖ {result.trackCount} tracks</span>
                                                                        )}
                                                                    </div>
                                                                </div>

                                                                {/* Duration (tracks only) */}
                                                                {!result.isPlaylist && result.duration > 0 && (
                                                                    <span className="text-[9px] text-white/25 tabular-nums shrink-0">
                                                                        {formatDuration(result.duration)}
                                                                    </span>
                                                                )}

                                                                {/* Download / Open button */}
                                                                <button
                                                                    onClick={() => handleDownload(result)}
                                                                    className={cn(
                                                                        "flex items-center gap-1 px-2 py-1 rounded text-[9px] font-medium transition-colors cursor-pointer opacity-60 group-hover:opacity-100",
                                                                        result.isPlaylist
                                                                            ? "bg-blue-500/10 border border-blue-500/20 text-blue-400/70 hover:bg-blue-500/20 hover:text-blue-300"
                                                                            : isInLibrary
                                                                                ? "bg-white/5 border border-white/10 text-white/30 hover:bg-white/10 hover:text-white/50"
                                                                                : "bg-green-500/10 border border-green-500/20 text-green-400/70 hover:bg-green-500/20 hover:text-green-300"
                                                                    )}
                                                                    title={result.isPlaylist ? "Open in download page" : isInLibrary ? "Already in library ΓÇö download again" : "Download and add to library"}
                                                                >
                                                                    {result.isPlaylist ? (
                                                                        <>
                                                                            <ExternalLink className="h-3 w-3" />
                                                                            <span className="hidden sm:inline">Open</span>
                                                                        </>
                                                                    ) : (
                                                                        <>
                                                                            <Download className="h-3 w-3" />
                                                                            <span className="hidden sm:inline">{isInLibrary ? "Re-Get" : "Get"}</span>
                                                                        </>
                                                                    )}
                                                                </button>
                                                            </div>
                                                        );
                                                    })}
                                                    {results.length > visibleCount && (
                                                        <button
                                                            onClick={() => loadMoreProvider(provider.id)}
                                                            className={cn(
                                                                "w-full py-2 text-[10px] hover:bg-white/[0.03] transition-colors cursor-pointer",
                                                                provider.color,
                                                                "opacity-60 hover:opacity-100"
                                                            )}
                                                        >
                                                            Show more ({results.length - visibleCount} remaining)
                                                        </button>
                                                    )}
                                                </>
                                            )}
                                        </>
                                    )}
                                </div>
                            );
                        })}

                        {/* Empty state when no providers and no local tracks */}
                        {!loading && tracks.length === 0 && enabledProviders.size === 0 && !search && (
                            <div className="flex flex-col items-center justify-center py-12 text-white/20 text-xs gap-2">
                                <Search className="h-6 w-6 opacity-30" />
                                Search your library or enable providers
                            </div>
                        )}
                    </div>
                </DialogContent>
            </Dialog>

            {/* Download progress modal */}
            {downloadTrack && (
                <InlineDownloadModal
                    open={downloadModalOpen}
                    track={downloadTrack}
                    targetDeck={targetDeck}
                    onLoadToDeck={handleLoadToDeck}
                    onAddedToLibrary={() => {
                        // Refresh local library so the new track is searchable
                        // and appears in the list as soon as the download +
                        // analyze pipeline finishes ΓÇö even before the user
                        // clicks "Load to Deck".
                        void fetchTracks(search);
                    }}
                    onClose={() => {
                        setDownloadModalOpen(false);
                        setDownloadTrack(null);
                    }}
                />
            )}
        </>
    );
}

