type ColorFxTarget = "A" | "B" | "LINK";

function ColorFxLinkSwitch({ value, onChange }: { value: ColorFxTarget; onChange: (v: ColorFxTarget) => void }) {
    const options: ColorFxTarget[] = ["A", "LINK", "B"];
