"use client";

/**
 * useRemoteLiveHost ΓÇö broadcasts LiveEngine state to remote peers
 * and handles incoming commands.
 *
 * Performance: the broadcast rAF loop only runs while a peer is actually
 * connected. The `live` context value is read through a ref so the effect
 * doesn't re-subscribe (and re-create the rAF loop) on every state change.
 * Realtime meter values are pulled from the meters store, not from `live`.
 */

import { useEffect, useRef } from "react";
import { useLive } from "@/components/live/live-context";
import { liveMetersStore } from "@/components/live/live-meters-store";
import { useRemoteOptional, type CommandHandler } from "@/components/remote/remote-context";
import type { LiveSnapshot, LiveLooperSnapshot, LivePadSnapshot, VPSnapshot } from "@/lib/remote-sync";
import type { FxType } from "@/lib/audio-fx-engine";

export function useRemoteLiveHost() {
    const live = useLive();
    const remote = useRemoteOptional();
    const liveRef = useRef(live);
    liveRef.current = live;

    const connectedPeerId = remote?.connectedPeerId ?? null;
    const broadcastState = remote?.broadcastState;
    const onCommand = remote?.onCommand;

    // Broadcast state at ~10fps ΓÇö only while a peer is connected. Pauses when
    // the tab is hidden. Reads `live` through a ref so we don't tear down and
    // rebuild the loop on every Provider re-render.
    useEffect(() => {
        if (!connectedPeerId || !broadcastState) return;

        let raf = 0;
        let lastBroadcast = 0;
        const BROADCAST_INTERVAL_MS = 100;

        const tick = () => {
            const now = performance.now();
            if (now - lastBroadcast >= BROADCAST_INTERVAL_MS) {
                lastBroadcast = now;
                const live = liveRef.current;
                const m = liveMetersStore.getSnapshot();

                const loopers: LiveLooperSnapshot[] = live.loopers.map(l => ({
                    id: l.id,
                    state: l.state,
                    durationBeats: l.durationBeats,
                    positionBeats: 0,
                    volume: l.volume,
                    muted: l.muted,
                }));

                const pads: LivePadSnapshot[] = live.pads.map(p => ({
                    id: p.id,
                    name: p.name,
                    color: p.color,
                    hasAudio: !!p.buffer,
                    isPlaying: p.isPlaying,
                    volume: p.volume,
                    loop: p.loop,
                }));

                const voice: VPSnapshot | null = live.voiceActive ? {
                    isActive: live.voiceActive,
                    inputGain: live.voiceInputGain,
                    outputGain: live.voiceOutputGain,
                    selectedKey: live.keyIndex,
                    selectedScale: live.scaleIndex,
                    chain: live.voiceChain.map(c => ({
                        id: c.id,
                        type: c.type,
                        enabled: c.enabled,
                        params: { ...c.params },
                    })),
                    peakL: m.voicePeakL,
                    peakR: m.voicePeakR,
                    rms: 0,
                    pitchNote: m.tunerNote,
                    pitchCents: m.tunerCents,
                    pitchConfidence: m.tunerConfidence,
                } : null;

                const snap: LiveSnapshot = {
                    page: "live",
                    masterVolume: live.masterVolume,
                    monitorVolume: live.monitorVolume,
                    masterPeakL: m.masterPeakL,
                    masterPeakR: m.masterPeakR,
                    isLimiting: m.isLimiting,
                    tempo: live.tempo,
                    isMetronomeOn: live.isMetronomeOn,
                    metronomeMonitorOnly: live.metronomeMonitorOnly,
                    keyIndex: live.keyIndex,
                    scaleIndex: live.scaleIndex,
                    isRecording: live.isRecording,
                    recordingDuration: m.recordingDuration,
                    backingLoaded: live.backingLoaded,
                    backingName: live.backingName,
                    backingIsPlaying: live.backingIsPlaying,
                    backingPosition: m.backingPosition,
                    backingDuration: live.backingDuration,
                    backingVolume: live.backingVolume,
                    backingTempoRatio: live.backingTempoRatio,
                    backingPitchSemis: live.backingPitchSemis,
                    backingLoopActive: live.backingLoopActive,
                    voice,
                    loopers,
                    activeLooperId: live.activeLooperId,
                    looperBeatLength: live.looperBeatLength,
                    pads,
                    tunerNote: m.tunerNote,
                    tunerCents: m.tunerCents,
                    tunerFrequency: m.tunerFrequency,
                    tunerConfidence: m.tunerConfidence,
                    tapCount: 0,
                    songs: [],
                    activeSongId: null,
                    // Compact spectrum/waveform for the remote visualizer widget.
                    // Generated on demand from the engine's hi-res analyser; cheap
                    // (~64 bytes/frame) and downsampled to be visualization-ready.
                    spectrum: live.engine?.getCompactSpectrum(32),
                    waveform: live.engine?.getCompactWaveform(32),
                };

                broadcastState(snap);
            }
            raf = requestAnimationFrame(tick);
        };
        raf = requestAnimationFrame(tick);

        const onVisibility = () => {
            if (document.hidden) {
                if (raf) { cancelAnimationFrame(raf); raf = 0; }
            } else if (raf === 0) {
                raf = requestAnimationFrame(tick);
            }
        };
        document.addEventListener("visibilitychange", onVisibility);

        return () => {
            document.removeEventListener("visibilitychange", onVisibility);
            if (raf) cancelAnimationFrame(raf);
        };
    }, [connectedPeerId, broadcastState]);

    // Handle commands
    useEffect(() => {
        if (!onCommand) return;
        const handler: CommandHandler = (action, args, ack) => {
            const live = liveRef.current;
            try {
                const [ns, method] = action.split(".");
                if (ns !== "live") return;

                switch (method) {
                    // Master / global
                    case "setMasterVolume": live.setMasterVolume(args[0] as number); break;
                    case "setMonitorVolume": live.setMonitorVolume(args[0] as number); break;
                    case "setTempo": live.setTempo(args[0] as number); break;
                    case "setKey": live.setKey(args[0] as number); break;
                    case "setScale": live.setScale(args[0] as number); break;
                    case "tap": live.tapBpm(); break;
                    case "toggleMetronome": live.toggleMetronome(); break;
                    case "setMetronomeMonitorOnly": live.setMetronomeMonitorOnly(args[0] as boolean); break;
                    case "setMetronomeVolume": live.setMetronomeVolume(args[0] as number); break;
                    case "toggleRecording": live.toggleRecording(); break;

                    // Backing track
                    case "backingToggle": live.backingToggle(); break;
                    case "backingStop": live.backingStop(); break;
                    case "backingSeek": live.backingSeek(args[0] as number); break;
                    case "setBackingVolume": live.setBackingVolume(args[0] as number); break;
                    case "setBackingTempoRatio": live.setBackingTempoRatio(args[0] as number); break;
                    case "setBackingPitchSemis": live.setBackingPitchSemis(args[0] as number); break;
                    case "setBackingLoop": live.setBackingLoop(args[0] as boolean); break;

                    // Voice
                    case "voiceStart": void live.voiceStart(args[0] as string | undefined); break;
                    case "voiceStop": void live.voiceStop(); break;
                    case "voiceSetInputGain": live.voiceSetInputGain(args[0] as number); break;
                    case "voiceSetOutputGain": live.voiceSetOutputGain(args[0] as number); break;
                    case "voiceAddEffect": live.voiceAddEffect(args[0] as FxType); break;
                    case "voiceRemoveEffect": live.voiceRemoveEffect(args[0] as string); break;
                    case "voiceToggleEffect": live.voiceToggleEffect(args[0] as string); break;
                    case "voiceUpdateParam": live.voiceUpdateParam(args[0] as string, args[1] as string, args[2] as number); break;
                    case "voiceClearChain": live.voiceClearChain(); break;

                    // Looper
                    case "toggleLooper": live.toggleLooper(args[0] as number); break;
                    case "clearLooper": live.clearLooper(args[0] as number); break;
                    case "setLooperVolume": live.setLooperVolume(args[0] as number, args[1] as number); break;
                    case "toggleLooperMute": live.toggleLooperMute(args[0] as number); break;
                    case "setLooperBeatLength": live.setLooperBeatLength(args[0] as number); break;
                    case "stopAllLoopers": live.stopAllLoopers(); break;

                    // Pads
                    case "triggerPad": live.triggerPad(args[0] as number); break;
                    case "stopPad": live.stopPad(args[0] as number); break;
                    case "setPadVolume": live.setPadVolume(args[0] as number, args[1] as number); break;
                    case "setPadLoop": live.setPadLoop(args[0] as number, args[1] as boolean); break;
                    case "clearPad": live.clearPad(args[0] as number); break;

                    default: ack(false, `Unknown live command: ${method}`); return;
                }
                ack(true);
            } catch (e) {
                ack(false, String(e));
            }
        };
        return onCommand(handler);
    }, [onCommand]);
}

"use client";

/**
 * useRemoteMixerHost ΓÇö broadcasts mixer state to remote peers
 * and handles incoming commands. Drop into the Mixer page.
 */

import { useEffect, useRef, useCallback } from "react";
import { useMixer } from "@/components/mixer-context";
import { useRemoteOptional, type CommandHandler } from "@/components/remote/remote-context";
import type { MixerSnapshot, MixerDeckSnapshot } from "@/lib/remote-sync";
import type { DeckState, DeckSide } from "@/lib/mixer-engine";

function deckToSnapshot(d: DeckState, track: { title: string; artist: string; artworkUrl: string | null } | null): MixerDeckSnapshot {
    return {
        trackId: d.trackId,
        trackTitle: track?.title || d.trackTitle || "",
        trackArtist: track?.artist || d.trackArtist || "",
        artworkUrl: track?.artworkUrl || d.trackArtworkUrl || null,
        isPlaying: d.isPlaying,
        isLoaded: d.isLoaded,
        currentTime: d.currentTime,
        duration: d.duration,
        bpm: d.bpm,
        originalBpm: d.originalBpm,
        key: d.key,
        volume: d.volume,
        eqLow: d.eqLow,
        eqMid: d.eqMid,
        eqHi: d.eqHi,
        eqLowKill: d.eqLowKill,
        eqMidKill: d.eqMidKill,
        eqHiKill: d.eqHiKill,
        filter: d.filter,
        filterType: d.filterType,
        colorFx: d.colorFx,
        colorFxType: d.colorFxType,
        beatFxOn: d.beatFxOn,
        beatFxType: d.beatFxType,
        beatFxAmount: d.beatFxAmount,
        beatFxBeatDiv: d.beatFxBeatDiv,
        loopEnabled: d.loopEnabled,
        loopBeats: d.loopBeats,
        hotCues: d.hotCues,
        headphoneCue: d.headphoneCue,
        padMode: d.padMode,
        slipMode: d.slipMode,
        quantize: d.quantize,
        keyLock: d.keyLock,
        keyShift: d.keyShift,
        crossfaderAssign: d.crossfaderAssign,
    };
}

export function useRemoteMixerHost() {
    const mixer = useMixer();
    const remote = useRemoteOptional();

    // Latest mixer via ref so the broadcast loop never has to be re-subscribed
    // when state changes (otherwise we'd tear down + rebuild the rAF/interval
    // every time currentTime ticks ΓÇö a major source of long tasks during play).
    const mixerRef = useRef(mixer);
    mixerRef.current = mixer;

    // Broadcast state at 15 Hz, *only* when we actually have a remote
    // controller subscribed. Previously we ran a rAF loop at 60 fps just to
    // gate a 15 fps broadcast; that burned one callback per frame for nothing
    // and kept the tab awake during idle.
    const broadcast = remote?.broadcastState;
    useEffect(() => {
        if (!broadcast) return;
        let timer: ReturnType<typeof setInterval> | null = null;
        let lastHash = "";
        const tick = () => {
            const m = mixerRef.current;
            // Cheap change-detection hash ΓÇö skip broadcast when nothing changed
            // (paused decks with a remote controller attached would otherwise
            // spam identical snapshots 15├ù/s).
            const h = `${m.deckA.currentTime}|${m.deckB.currentTime}|${m.deckC.currentTime}|${m.deckD.currentTime}|` +
                `${m.deckA.isPlaying}|${m.deckB.isPlaying}|${m.deckC.isPlaying}|${m.deckD.isPlaying}|` +
                `${m.crossfader}|${m.masterVolume}|${m.isRecording}|${m.recordingDuration}|${m.deckMode}|` +
                `${m.deckA.trackId}|${m.deckB.trackId}|${m.deckC.trackId}|${m.deckD.trackId}|${m.automixEnabled}`;
            if (h === lastHash) return;
            lastHash = h;
            const snap: MixerSnapshot = {
                page: "mixer",
                deckA: deckToSnapshot(m.deckA, m.deckATrack ? { title: m.deckATrack.title || "", artist: m.deckATrack.artist || "", artworkUrl: m.deckATrack.artworkUrl || null } : null),
                deckB: deckToSnapshot(m.deckB, m.deckBTrack ? { title: m.deckBTrack.title || "", artist: m.deckBTrack.artist || "", artworkUrl: m.deckBTrack.artworkUrl || null } : null),
                deckC: deckToSnapshot(m.deckC, m.deckCTrack ? { title: m.deckCTrack.title || "", artist: m.deckCTrack.artist || "", artworkUrl: m.deckCTrack.artworkUrl || null } : null),
                deckD: deckToSnapshot(m.deckD, m.deckDTrack ? { title: m.deckDTrack.title || "", artist: m.deckDTrack.artist || "", artworkUrl: m.deckDTrack.artworkUrl || null } : null),
                deckMode: m.deckMode,
                crossfader: m.crossfader,
                crossfaderCurve: m.crossfaderCurve,
                masterVolume: m.masterVolume,
                headphoneVolume: m.headphoneVolume,
                headphoneMix: m.headphoneMix,
                eqMode: m.eqMode,
                tempoRange: m.tempoRange,
                isRecording: m.isRecording,
                recordingDuration: m.recordingDuration,
                automixEnabled: m.automixEnabled,
                samplerSlots: m.samplerSlots.map(s => ({
                    id: s.id,
                    name: s.name,
                    isPlaying: s.isPlaying,
                    volume: s.volume,
                    isLooping: s.isLooping,
                    hasAudio: s.buffer !== null,
                })),
            };
            broadcast(snap);
        };
        timer = setInterval(tick, 66); // ~15 Hz
        return () => { if (timer) clearInterval(timer); };
    }, [broadcast]);

    // Handle commands ΓÇö subscribe once, dispatch through the ref so we
    // never re-subscribe (previously this tore down + rebuilt the handler
    // on every state change, which is many times per second during play).
    const onCommand = remote?.onCommand;
    useEffect(() => {
        if (!onCommand) return;
        const handler: CommandHandler = (action, args, ack) => {
            const mixer = mixerRef.current;
            try {
                const [ns, method] = action.split(".");
                if (ns !== "mixer") return;
                const deck = args[0] as DeckSide;

                switch (method) {
                    case "play": mixer.play(deck); break;
                    case "pause": mixer.pause(deck); break;
                    case "togglePlay": mixer.togglePlay(deck); break;
                    case "setVolume": mixer.setVolume(deck, args[1] as number); break;
                    case "setEQ": mixer.setEQ(deck, args[1] as "low" | "mid" | "hi", args[2] as number); break;
                    case "toggleEQKill": mixer.toggleEQKill(deck, args[1] as "low" | "mid" | "hi"); break;
                    case "setFilter": mixer.setFilter(deck, args[1] as number); break;
                    case "setCrossfader": mixer.setCrossfader(args[0] as number); break;
                    case "setMasterVolume": mixer.setMasterVolume(args[0] as number); break;
                    case "setHeadphoneVolume": mixer.setHeadphoneVolume(args[0] as number); break;
                    case "setHeadphoneMix": mixer.setHeadphoneMix(args[0] as number); break;
                    case "toggleHeadphoneCue": mixer.toggleHeadphoneCue(deck); break;
                    case "setColorFx": mixer.setColorFx(deck, args[1] as number); break;
                    case "setColorFxType": mixer.setColorFxType(deck, args[1] as Parameters<typeof mixer.setColorFxType>[1]); break;
                    case "setBeatFxAmount": mixer.setBeatFxAmount(deck, args[1] as number); break;
                    case "setBeatFx": mixer.setBeatFx(deck, args[1] as Parameters<typeof mixer.setBeatFx>[1]); break;
                    case "toggleBeatFx": mixer.toggleBeatFx(deck); break;
                    case "setBeatFxBeatDiv": mixer.setBeatFxBeatDiv(deck, args[1] as number); break;
                    case "setFilterType": mixer.setFilterType(deck, args[1] as Parameters<typeof mixer.setFilterType>[1]); break;
                    case "jumpHotCue": mixer.jumpHotCue(deck, args[1] as number); break;
                    case "setHotCue": mixer.setHotCue(deck, args[1] as number); break;
                    case "clearHotCue": mixer.clearHotCue(deck, args[1] as number); break;
                    case "setLoop": mixer.setLoop(deck, args[1] as number); break;
                    case "toggleLoop": mixer.toggleLoop(deck); break;
                    case "moveLoop": mixer.moveLoop(deck, args[1] as "left" | "right"); break;
                    case "nudge": mixer.nudge(deck, args[1] as number); break;
                    case "nudgeRelease": mixer.nudgeRelease(deck); break;
                    case "beatJump": mixer.beatJump(deck, args[1] as number); break;
                    case "syncBpm": mixer.syncBpm(deck); break;
                    case "setKeyShift": mixer.setKeyShift(deck, args[1] as number); break;
                    case "setKeyLock": mixer.setKeyLock(deck, args[1] as boolean); break;
                    case "toggleSlipMode": mixer.toggleSlipMode(deck); break;
                    case "toggleQuantize": mixer.toggleQuantize(deck); break;
                    case "setPadMode": mixer.setPadMode(deck, args[1] as Parameters<typeof mixer.setPadMode>[1]); break;
                    case "setCrossfaderAssign": mixer.setCrossfaderAssign(deck, args[1] as Parameters<typeof mixer.setCrossfaderAssign>[1]); break;
                    case "ejectTrack": mixer.ejectTrack(deck); break;
                    // Global
                    case "setCrossfaderCurve": mixer.setCrossfaderCurve(args[0] as Parameters<typeof mixer.setCrossfaderCurve>[0]); break;
                    case "setEQMode": mixer.setEQMode(args[0] as Parameters<typeof mixer.setEQMode>[0]); break;
                    case "setTempoRange": mixer.setTempoRange(args[0] as number); break;
                    case "setDeckMode": mixer.setDeckMode(args[0] as Parameters<typeof mixer.setDeckMode>[0]); break;
                    case "toggleRecording": mixer.toggleRecording(); break;
                    case "toggleAutomix": mixer.toggleAutomix(); break;
                    // Sampler
                    case "triggerSampler": mixer.triggerSampler(args[0] as number); break;
                    case "stopSampler": mixer.stopSampler(args[0] as number); break;
                    case "toggleSamplerLoop": mixer.toggleSamplerLoop(args[0] as number); break;
                    default: ack(false, `Unknown mixer command: ${method}`); return;
                }
                ack(true);
            } catch (e) {
                ack(false, String(e));
            }
        };
        return onCommand(handler);
    }, [onCommand]);
}

