                        />
                        <RemoteFader
                            value={snapshot.headphoneVolume}
                            min={0} max={1.5}
                            color="#eab308"
                            label="Headphone"
                            onChange={v => sendCommand("mixer.setHeadphoneVolume", v)}
                            onDoubleClick={() => sendCommand("mixer.setHeadphoneVolume", 1)}
                            showValue
                        />
                        <RemoteFader
                            value={snapshot.headphoneMix}
                            min={0} max={1}
                            color="#06b6d4"
