                        {snapshot.isRecording ? `ΓÅ║ Recording ΓÇö ${Math.floor(snapshot.recordingDuration / 1000)}s` : "ΓÅ║ Start Recording"}
                    </button>
                </div>
            </RemotePanel>

            {/* Deck cards */}
            <RemotePanel id="decks" label="Decks">
                <div className={cn("grid gap-3", is4 ? "grid-cols-1 sm:grid-cols-2" : "grid-cols-1 sm:grid-cols-2")}>
