"use client";

import { useState, useCallback, useRef, useEffect, useReducer, memo } from "react";
import { subscribeRaf } from "@/lib/raf-scheduler";
import {
    type StemType,
    type StemConfig,
    STEM_TYPES,
    STEM_LABELS,
    STEM_COLORS,
    createDefaultStemConfigs,
    RealtimeStemProcessor,
} from "@/lib/stems-engine";
import { cn } from "@/lib/utils";
import { useRenderCount } from "@/lib/dev-debugger";
import {
    Mic,
    Drum,
    Music,
    Piano,
    Volume2,
    VolumeX,
    Headphones,
    Power,
    ChevronDown,
    ChevronUp,
} from "lucide-react";

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface StemsPanelProps {
    processor: RealtimeStemProcessor | null;
    compact?: boolean;
    deckColor?: string;
    className?: string;
}

interface StemControlProps {
    config: StemConfig;
    color: string;
    level: number;
    compact?: boolean;
    onVolumeChange: (volume: number) => void;
    onToggleMute: () => void;
    onToggleSolo: () => void;
}

const STEM_ICON_MAP: Record<StemType, typeof Mic> = {
    vocals: Mic,
    drums: Drum,
    bass: Music,
    melody: Piano,
};

// ΓöÇΓöÇΓöÇ Stem Level Meter ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function useStemLevels(processor: RealtimeStemProcessor | null) {
    const [levels, setLevels] = useState<Record<StemType, number>>({
        vocals: 0, drums: 0, bass: 0, melody: 0,
    });
    const dataRef = useRef(new Float32Array(128));
    const lastRef = useRef<Record<StemType, number>>({
        vocals: 0, drums: 0, bass: 0, melody: 0,
    });

    useEffect(() => {
        if (!processor?.isActive) {
            setLevels({ vocals: 0, drums: 0, bass: 0, melody: 0 });
            return;
        }

        const update = () => {
            let changed = false;
            const last = lastRef.current;
            const next: Record<StemType, number> = { ...last };

            for (const stem of STEM_TYPES) {
                const analyser = processor.getAnalyser(stem);
                if (!analyser) continue;

                if (dataRef.current.length !== analyser.fftSize) {
                    dataRef.current = new Float32Array(analyser.fftSize);
                }
                analyser.getFloatTimeDomainData(dataRef.current);

                let max = 0;
                const buf = dataRef.current;
                for (let i = 0; i < buf.length; i += 2) {  // sample every other point
                    const abs = Math.abs(buf[i]);
                    if (abs > max) max = abs;
                }
                // Skip writes when nothing visibly changed (cheap early exit).
                if (Math.abs(max - last[stem]) > 0.015) {
                    next[stem] = max;
                    changed = true;
                }
            }

            if (changed) {
                lastRef.current = next;
                setLevels(next);
            }
        };

        // 30 fps is plenty for a level-meter ring; halves the React re-render
        // cost compared to the previous unthrottled rAF, and the shared
        // scheduler avoids spinning up a private rAF loop per processor.
        return subscribeRaf(update, { fps: 30 });
    }, [processor, processor?.isActive]);

    return levels;
}

// ΓöÇΓöÇΓöÇ Stem Control ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const StemControl = memo(function StemControl({
    config,
    color,
    level,
    compact,
    onVolumeChange,
    onToggleMute,
    onToggleSolo,
}: StemControlProps) {
    const Icon = STEM_ICON_MAP[config.type];
    const isActive = !config.muted && config.volume > 0;
    const isSoloed = config.solo;
    const effectiveLevel = config.muted ? 0 : level * config.volume;

    const sliderRef = useRef<HTMLDivElement>(null);
    const isDragging = useRef(false);

    const handlePointerDown = useCallback((e: React.PointerEvent) => {
        e.preventDefault();
        isDragging.current = true;
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        updateFromPointer(e);
    }, []);

    const handlePointerMove = useCallback((e: React.PointerEvent) => {
        if (!isDragging.current) return;
        updateFromPointer(e);
    }, []);

    const handlePointerUp = useCallback(() => {
        isDragging.current = false;
    }, []);

    const updateFromPointer = useCallback((e: React.PointerEvent) => {
        const rect = sliderRef.current?.getBoundingClientRect();
        if (!rect) return;
        const y = 1 - Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height));
        onVolumeChange(y);
    }, [onVolumeChange]);

    if (compact) {
        return (
            <div className="flex flex-col items-center gap-1">
                <button
                    onClick={onToggleMute}
                    className={cn(
                        "relative flex items-center justify-center w-8 h-8 rounded-lg transition-all duration-200",
                        isActive
                            ? "bg-white/10 hover:bg-white/15"
                            : "bg-white/5 hover:bg-white/10 opacity-40",
                    )}
                    title={`${STEM_LABELS[config.type]}: ${config.muted ? "Unmute" : "Mute"}`}
                >
                    <Icon className="w-3.5 h-3.5" style={{ color: isActive ? color : undefined }} />
                    {/* Level indicator ring */}
                    <div
                        className="absolute inset-0 rounded-lg border-2 transition-opacity duration-100"
                        style={{
                            borderColor: color,
                            opacity: effectiveLevel * 0.8,
                        }}
                    />
                </button>
                <span className="text-[9px] text-[var(--muted-foreground)] leading-none">
                    {STEM_LABELS[config.type].slice(0, 3)}
                </span>
            </div>
        );
    }

    return (
        <div className="flex flex-col items-center gap-1.5 select-none">
            {/* Label */}
            <span
                className="text-[10px] font-medium tracking-wider uppercase"
                style={{ color }}
            >
                {STEM_LABELS[config.type]}
            </span>

            {/* Volume slider (vertical) */}
            <div
                ref={sliderRef}
                className="relative w-6 h-20 rounded-full bg-white/5 cursor-pointer overflow-hidden"
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
            >
                {/* Volume fill */}
                <div
                    className="absolute bottom-0 left-0 right-0 rounded-full transition-[height] duration-75"
                    style={{
                        height: `${config.volume * 100}%`,
                        background: `linear-gradient(to top, ${color}40, ${color}80)`,
                    }}
                />
                {/* Level meter overlay */}
                <div
                    className="absolute bottom-0 left-0 right-0 transition-[height] duration-75"
                    style={{
                        height: `${effectiveLevel * 100}%`,
                        background: `${color}30`,
                    }}
                />
                {/* Thumb */}
                <div
                    className="absolute left-1/2 -translate-x-1/2 w-4 h-1.5 rounded-full bg-white shadow-sm transition-[bottom] duration-75"
                    style={{ bottom: `calc(${config.volume * 100}% - 3px)` }}
                />
            </div>

            {/* Volume percentage */}
            <span className="text-[9px] text-[var(--muted-foreground)] tabular-nums">
                {Math.round(config.volume * 100)}%
            </span>

            {/* Buttons row */}
            <div className="flex items-center gap-0.5">
                {/* Mute */}
                <button
                    onClick={onToggleMute}
                    className={cn(
                        "flex items-center justify-center w-6 h-6 rounded transition-all duration-150",
                        config.muted
                            ? "bg-red-500/20 text-red-400"
                            : "bg-white/5 text-[var(--muted-foreground)] hover:bg-white/10 hover:text-[var(--foreground)]",
                    )}
                    title={config.muted ? "Unmute" : "Mute"}
                >
                    {config.muted ? (
                        <VolumeX className="w-3 h-3" />
                    ) : (
                        <Volume2 className="w-3 h-3" />
                    )}
                </button>

                {/* Solo */}
                <button
                    onClick={onToggleSolo}
                    className={cn(
                        "flex items-center justify-center w-6 h-6 rounded text-[10px] font-bold transition-all duration-150",
                        isSoloed
                            ? "text-amber-400"
                            : "bg-white/5 text-[var(--muted-foreground)] hover:bg-white/10 hover:text-[var(--foreground)]",
                    )}
                    style={isSoloed ? { backgroundColor: `${color}30` } : undefined}
                    title={isSoloed ? "Unsolo" : "Solo"}
                >
                    S
                </button>
            </div>

            {/* Icon */}
            <div
                className={cn(
                    "flex items-center justify-center w-7 h-7 rounded-lg transition-all duration-200",
                    isActive ? "bg-white/10" : "bg-white/5 opacity-40",
                )}
            >
                <Icon className="w-3.5 h-3.5" style={{ color: isActive ? color : undefined }} />
            </div>
        </div>
    );
});

// ΓöÇΓöÇΓöÇ Stems Panel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const StemsPanel = memo(function StemsPanel({
    processor,
    compact = false,
    deckColor,
    className,
}: StemsPanelProps) {
    useRenderCount("StemsPanel");
    const [isExpanded, setIsExpanded] = useState(!compact);
    const [, forceRender] = useReducer(x => x + 1, 0);
    const levels = useStemLevels(processor);

    const configs = processor?.configs ?? createDefaultStemConfigs();
    const isActive = processor?.isActive ?? false;

    const handleToggle = useCallback(() => {
        processor?.toggle();
        forceRender();
    }, [processor]);

    const handleVolumeChange = useCallback((stem: StemType, volume: number) => {
        processor?.setStemVolume(stem, volume);
        forceRender();
    }, [processor]);

    const handleToggleMute = useCallback((stem: StemType) => {
        processor?.toggleStemMute(stem);
        forceRender();
    }, [processor]);

    const handleToggleSolo = useCallback((stem: StemType) => {
        processor?.toggleStemSolo(stem);
        forceRender();
    }, [processor]);

    if (!processor) return null;

    return (
        <div
            className={cn(
                "flex flex-col rounded-xl border transition-all duration-300",
                isActive
                    ? "border-purple-500/30 bg-purple-500/5"
                    : "border-[var(--border)] bg-[var(--card)]/50",
                className,
            )}
        >
            {/* Header */}
            <div className="flex items-center justify-between px-3 py-2">
                <div className="flex items-center gap-2">
                    <button
                        onClick={handleToggle}
                        className={cn(
                            "flex items-center justify-center w-7 h-7 rounded-lg transition-all duration-200",
                            isActive
                                ? "bg-purple-500/20 text-purple-400 shadow-[0_0_8px_rgba(168,85,247,0.3)]"
                                : "bg-white/5 text-[var(--muted-foreground)] hover:bg-white/10",
                        )}
                    >
                        <Power className="w-3.5 h-3.5" />
                    </button>
                    <span className="text-xs font-semibold tracking-wide uppercase text-[var(--muted-foreground)]">
                        Stems
                    </span>
                    {isActive && (
                        <span className="flex items-center gap-1 px-1.5 py-0.5 rounded-full bg-purple-500/15 text-[9px] font-medium text-purple-400 animate-[fadeIn_200ms_ease-out]">
                            <span className="w-1 h-1 rounded-full bg-purple-400 animate-pulse" />
                            Active
                        </span>
                    )}
                </div>

                {!compact && (
                    <button
                        onClick={() => setIsExpanded(!isExpanded)}
                        className="flex items-center justify-center w-6 h-6 rounded text-[var(--muted-foreground)] hover:text-[var(--foreground)] hover:bg-white/5 transition-colors"
                    >
                        {isExpanded ? (
                            <ChevronUp className="w-3.5 h-3.5" />
                        ) : (
                            <ChevronDown className="w-3.5 h-3.5" />
                        )}
                    </button>
                )}
            </div>

            {/* Stem controls */}
            {isActive && (isExpanded || compact) && (
                <div
                    className={cn(
                        "px-3 pb-3 animate-[fadeIn_200ms_ease-out]",
                        compact ? "flex items-center justify-center gap-3" : "flex items-end justify-center gap-4",
                    )}
                >
                    {STEM_TYPES.map((stemType) => {
                        const config = configs.find(c => c.type === stemType);
                        if (!config) return null;
                        return (
                            <StemControl
                                key={stemType}
                                config={config}
                                color={STEM_COLORS[stemType]}
                                level={levels[stemType]}
                                compact={compact}
                                onVolumeChange={(v) => handleVolumeChange(stemType, v)}
                                onToggleMute={() => handleToggleMute(stemType)}
                                onToggleSolo={() => handleToggleSolo(stemType)}
                            />
                        );
                    })}
                </div>
            )}
        </div>
    );
});

// ΓöÇΓöÇΓöÇ Compact Stems Strip (for tight spaces) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const StemsStrip = memo(function StemsStrip({
    processor,
    className,
}: {
    processor: RealtimeStemProcessor | null;
    className?: string;
}) {
    const [, forceRender] = useReducer(x => x + 1, 0);
    const levels = useStemLevels(processor);
    const configs = processor?.configs ?? createDefaultStemConfigs();
    const isActive = processor?.isActive ?? false;

    if (!processor) return null;

    return (
        <div className={cn("flex items-center gap-1", className)}>
            <button
                onClick={() => { processor.toggle(); forceRender(); }}
                className={cn(
                    "flex items-center justify-center w-6 h-6 rounded transition-all duration-150",
                    isActive
                        ? "bg-purple-500/20 text-purple-400"
                        : "bg-white/5 text-[var(--muted-foreground)] hover:bg-white/10",
                )}
                title="Toggle Stems"
            >
                <Power className="w-3 h-3" />
            </button>

            {isActive && STEM_TYPES.map((stemType) => {
                const config = configs.find(c => c.type === stemType);
                if (!config) return null;
                const Icon = STEM_ICON_MAP[stemType];
                const active = !config.muted && config.volume > 0;
                const level = levels[stemType];

                return (
                    <button
                        key={stemType}
                        onClick={() => { processor.toggleStemMute(stemType); forceRender(); }}
                        className={cn(
                            "relative flex items-center justify-center w-6 h-6 rounded transition-all duration-150",
                            active
                                ? "bg-white/10 hover:bg-white/15"
                                : "bg-white/5 opacity-40 hover:opacity-60",
                        )}
                        title={`${STEM_LABELS[stemType]}: ${config.muted ? "Unmute" : "Mute"}`}
                    >
                        <Icon className="w-3 h-3" style={{ color: active ? STEM_COLORS[stemType] : undefined }} />
                        {/* Level dot */}
                        <span
                            className="absolute -bottom-0.5 left-1/2 -translate-x-1/2 w-1 h-1 rounded-full transition-opacity"
                            style={{
                                backgroundColor: STEM_COLORS[stemType],
                                opacity: level * 0.8,
                            }}
                        />
                    </button>
                );
            })}
        </div>
    );
});

"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { usePlayer } from "./player-context";
import { Artwork } from "./artwork";
import { ChevronUp, ChevronDown, Pause } from "lucide-react";
import { cn, formatKey } from "@/lib/utils";
import { useDAWSettings } from "@/hooks/use-daw-settings";
import { usePathname } from "next/navigation";

/** Walk up from `el` to find the nearest scrollable ancestor (overflow-y
 *  set to auto/scroll). Falls back to `<main>`, then `null`. */
function findScrollParent(el: HTMLElement | null): HTMLElement | null {
    let node = el?.parentElement ?? null;
    while (node) {
        const style = window.getComputedStyle(node);
        const oy = style.overflowY;
        if ((oy === "auto" || oy === "scroll") && node.scrollHeight > node.clientHeight) {
            return node;
        }
        node = node.parentElement;
    }
    return document.querySelector<HTMLElement>("main");
}

export function StickyNowPlaying() {
    const player = usePlayer();
    const { noteNotations } = useDAWSettings();
    const pathname = usePathname();
    const [position, setPosition] = useState<"above" | "below" | null>(null);
    const [mainRect, setMainRect] = useState<{ left: number; width: number } | null>(null);
    const observerRef = useRef<IntersectionObserver | null>(null);
    const rafRef = useRef<number>(0);
    const buttonRef = useRef<HTMLButtonElement>(null);
    /** Scroll container we currently apply spacer padding to, plus the
     *  pre-existing inline padding values so we can restore them on unmount
     *  / when the bar hides. */
    const paddedContainerRef = useRef<{
        el: HTMLElement;
        prevPaddingTop: string;
        prevPaddingBottom: string;
    } | null>(null);

    const scrollToTrack = useCallback(() => {
        const row = document.querySelector<HTMLElement>("[data-playing-track]");
        if (row) {
            row.scrollIntoView({ behavior: "smooth", block: "center" });
        }
    }, []);

    // Track the <main> element's position for sizing the bar
    useEffect(() => {
        const main = document.querySelector<HTMLElement>("main");
        if (!main) return;

        const update = () => {
            const rect = main.getBoundingClientRect();
            setMainRect({ left: rect.left, width: rect.width });
        };

        update();
        const ro = new ResizeObserver(update);
        ro.observe(main);

        return () => ro.disconnect();
    }, []);

    useEffect(() => {
        setPosition(null);

        if (!player.currentTrack) return;

        const setup = () => {
            const row = document.querySelector<HTMLElement>("[data-playing-track]");
            if (!row) {
                setPosition(null);
                return;
            }

            const main = document.querySelector<HTMLElement>("main");
            if (!main) return;

            observerRef.current?.disconnect();

            const observer = new IntersectionObserver(
                (entries) => {
                    const entry = entries[0];
                    if (!entry) return;

                    if (entry.isIntersecting) {
                        setPosition(null);
                    } else {
                        const rowTop = entry.boundingClientRect.top;
                        const rootTop = entry.rootBounds?.top ?? 0;
                        setPosition(rowTop < rootTop ? "above" : "below");
                    }
                },
                {
                    root: main,
                    threshold: 0,
                    rootMargin: "0px",
                }
            );

            observer.observe(row);
            observerRef.current = observer;
        };

        const timer = setTimeout(setup, 150);

        // The MutationObserver was previously firing on EVERY childList
        // mutation in <main> with subtree:true ΓÇö on the /analysis page that
        // adds 400+ log rows per session, this burned a rAF + querySelector
        // for every single log line. Now we cheap-filter mutations: only
        // re-setup if the playing-track row was actually added/removed.
        const mutationObs = new MutationObserver((mutations) => {
            for (const m of mutations) {
                for (let i = 0; i < m.addedNodes.length; i++) {
                    const n = m.addedNodes[i];
                    if (n instanceof HTMLElement && (n.matches?.("[data-playing-track]") || n.querySelector?.("[data-playing-track]"))) {
                        cancelAnimationFrame(rafRef.current);
                        rafRef.current = requestAnimationFrame(setup);
                        return;
                    }
                }
                for (let i = 0; i < m.removedNodes.length; i++) {
                    const n = m.removedNodes[i];
                    if (n instanceof HTMLElement && (n.matches?.("[data-playing-track]") || n.querySelector?.("[data-playing-track]"))) {
                        cancelAnimationFrame(rafRef.current);
                        rafRef.current = requestAnimationFrame(setup);
                        return;
                    }
                }
            }
        });

        const main = document.querySelector("main");
        if (main) {
            mutationObs.observe(main, { childList: true, subtree: true });
        }

        return () => {
            clearTimeout(timer);
            cancelAnimationFrame(rafRef.current);
            mutationObs.disconnect();
            observerRef.current?.disconnect();
        };
    }, [player.currentTrack?.id, pathname]);

    // While the sticky bar is visible it floats over the scroll container
    // (it's `position: fixed`). Without compensating padding the very last
    // row(s) of the underlying list ΓÇö including the pagination bar on the
    // Library / Playlists / Hidden pages ΓÇö sit underneath the bar and the
    // user can't reach them by scrolling. Push an inline padding equal to
    // the bar's measured height onto the closest scrollable ancestor of
    // the playing row, on the matching side, and restore the original
    // value when the bar hides.
    useEffect(() => {
        const release = () => {
            const prev = paddedContainerRef.current;
            if (!prev) return;
            prev.el.style.paddingTop = prev.prevPaddingTop;
            prev.el.style.paddingBottom = prev.prevPaddingBottom;
            paddedContainerRef.current = null;
        };

        if (!position || !player.currentTrack) {
            release();
            return;
        }

        // Defer one frame so the bar's DOM is committed and offsetHeight is real.
        const id = requestAnimationFrame(() => {
            const row = document.querySelector<HTMLElement>("[data-playing-track]");
            const scrollEl = findScrollParent(row);
            const bar = buttonRef.current;
            if (!scrollEl || !bar) return;

            // If we're moving the spacer to a different container, release
            // the old one first so we don't leak padding on the previous page.
            if (paddedContainerRef.current && paddedContainerRef.current.el !== scrollEl) {
                release();
            }

            // Snapshot the original inline padding the first time we touch
            // this element so we can restore it cleanly later.
            if (!paddedContainerRef.current) {
                paddedContainerRef.current = {
                    el: scrollEl,
                    prevPaddingTop: scrollEl.style.paddingTop,
                    prevPaddingBottom: scrollEl.style.paddingBottom,
                };
            }

            const h = bar.offsetHeight + 8; // small breathing room
            if (position === "below") {
                scrollEl.style.paddingBottom = `${h}px`;
                scrollEl.style.paddingTop = paddedContainerRef.current.prevPaddingTop;
            } else {
                scrollEl.style.paddingTop = `${h}px`;
                scrollEl.style.paddingBottom = paddedContainerRef.current.prevPaddingBottom;
            }
        });

        return () => {
            cancelAnimationFrame(id);
            release();
        };
    }, [position, player.currentTrack?.id, pathname]);

    if (!position || !player.currentTrack) return null;

    const track = player.currentTrack;
    const isAbove = position === "above";

    return (
        <button
            ref={buttonRef}
            onClick={scrollToTrack}
            style={mainRect ? { left: mainRect.left, width: mainRect.width } : undefined}
            className={cn(
                "fixed z-40 flex items-center gap-3 px-4 py-2 bg-card/95 backdrop-blur-sm shadow-lg cursor-pointer transition-all duration-200 hover:bg-card group border-purple-500/30",
                isAbove
                    ? "top-0 border-b"
                    : "bottom-[73px] border-t"
            )}
        >
            {/* Direction indicator */}
            <div className="flex h-6 w-6 items-center justify-center rounded-full bg-purple-500/10 text-purple-400 group-hover:bg-purple-500/20 transition-colors shrink-0">
                {isAbove ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
            </div>

            {/* Artwork */}
            <Artwork src={track.artworkUrl} size="sm" showPlaceholder={false} />

            {/* Track info */}
            <div className="flex-1 min-w-0 text-left">
                <p className="text-sm font-medium text-purple-400 truncate">
                    {track.title || track.filename}
                </p>
                <p className="text-xs text-muted-foreground truncate">
                    {track.artist || "Unknown"}
                </p>
            </div>

            {/* BPM / Key badges */}
            <div className="hidden sm:flex items-center gap-2">
                {track.bpm && (
                    <span className="text-xs font-mono text-muted-foreground tabular-nums">
                        {Math.round(track.bpm)} BPM
                    </span>
                )}
                {track.keyCamelot && (
                    <span className="text-xs font-mono text-muted-foreground">
                        {formatKey(track.keyCamelot, noteNotations)}
                    </span>
                )}
            </div>

            {/* Playing indicator */}
            <div className="flex items-center gap-1.5 shrink-0">
                {player.isPlaying ? (
                    <div className="flex items-center gap-0.5">
                        <span className="w-0.5 h-3 bg-purple-400 rounded-full animate-pulse" />
                        <span className="w-0.5 h-4 bg-purple-400 rounded-full animate-pulse [animation-delay:150ms]" />
                        <span className="w-0.5 h-2.5 bg-purple-400 rounded-full animate-pulse [animation-delay:300ms]" />
                    </div>
                ) : (
                    <Pause className="h-3.5 w-3.5 text-purple-400" />
                )}
            </div>

            {/* Label */}
            <span className="text-[10px] text-muted-foreground/50 uppercase tracking-wider shrink-0">
                {isAbove ? "Γåæ Scroll to track" : "Γåô Scroll to track"}
            </span>
        </button>
    );
}

