    return current;
}

// ΓöÇΓöÇΓöÇ Hook ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

let refCount = 0;

export function useSystemStats(gpuIndex = 0, pollInterval = 5): SystemStats {
    const prevRef = useRef({ gpuIndex, pollInterval });

    useEffect(() => {
        refCount++;
        connect(gpuIndex, pollInterval);

        return () => {
            refCount--;
            if (refCount <= 0) {
                refCount = 0;
                disconnect();
            }
        };
    }, []);

    // Reconnect if params change
    useEffect(() => {
